/**
 * @module dashboard
 * @see docs/modules/dashboard.md
 */
    /* ===================================================================== *
     *  DASHBOARD — estimates tweepcred from public signals + recommendations *
     * ===================================================================== */
    const Dashboard = {
        firstShow: true,
        _statsFetched: false,
        _statsFetching: false,

        onShow() {
            if (this.firstShow) {
                this.render();
                this.firstShow = false;
            }
            // Re-run on every visit so values fill in once you've reached your
            // profile (and so the API fetch gets another chance). Existing/edited
            // fields are never overwritten.
            this.autofill();
        },

        render() {
            UI.el('tpm-pane-dashboard').innerHTML = `
              <div class="tpm-section">
                <h4>Tweepcred (legacy 2023 algorithm)</h4>
                <p>This reproduces X's open-source <code>UserMass</code> + reputation adjustment <strong>exactly</strong>. The score X actually published also ran a global PageRank over the follow graph, which can't be computed in a browser, so this is the per-user mass that <em>seeds</em> that PageRank. Below ~65, the old search filter cut an account's eligible tweets to about 3.</p>
                <div class="tpm-score">
                  <div class="tpm-score-num" id="tpm-score-num">–</div>
                  <div class="tpm-score-meta">
                    <div class="tpm-score-label" id="tpm-score-label">Enter your numbers below</div>
                    <div class="tpm-track"><div class="tpm-fill" id="tpm-score-fill"></div></div>
                  </div>
                </div>
                <div id="tpm-factors" style="margin-top:14px"></div>
              </div>

              <div class="tpm-section">
                <h4>Account</h4>
                <p>Look up any public handle, or use your own (auto-filled). Numbers stay editable.</p>
                <label class="tpm-label" for="tpm-d-handle">Handle</label>
                <div class="tpm-row">
                  <div style="flex:2"><input id="tpm-d-handle" type="text" class="tpm-input" placeholder="@username"></div>
                  <div><button class="tpm-btn tpm-btn-ghost" id="tpm-d-lookup" type="button">Look up</button></div>
                </div>
                <div class="tpm-row">
                  <div><label class="tpm-label">Followers</label><input id="tpm-d-followers" type="number" class="tpm-input" placeholder="0"></div>
                  <div><label class="tpm-label">Following</label><input id="tpm-d-following" type="number" class="tpm-input" placeholder="0"></div>
                </div>
                <label class="tpm-label" for="tpm-d-age">Account age (days) — only the first ~30 days matter</label>
                <input id="tpm-d-age" type="number" class="tpm-input" placeholder="e.g. 365">
                <label class="tpm-check"><input type="checkbox" id="tpm-d-verified"> Legacy verified (old blue check; sets mass to 100). X Premium does NOT count here.</label>
                <label class="tpm-check"><input type="checkbox" id="tpm-d-device" checked> Valid device / verified phone (assumed; can't be read)</label>
                <label class="tpm-check"><input type="checkbox" id="tpm-d-restricted"> Account restricted (×0.1 penalty)</label>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-primary" id="tpm-d-calc" type="button">Recalculate</button>
                </div>
                <p id="tpm-d-status" class="tpm-note" style="margin-top:8px"></p>
              </div>

              <div class="tpm-section">
                <h4>Recommendations</h4>
                <ul id="tpm-recs"><li>Fill in your numbers and recalculate.</li></ul>
              </div>
              <div class="tpm-foot">Exact reproduction of UserMass.scala + Reputation.scala (minus the global PageRank stage).</div>`;

            UI.el('tpm-d-calc').onclick = () => this.calculate();
            UI.el('tpm-d-lookup').onclick = () => {
                const h = (UI.el('tpm-d-handle').value || '').replace(/^@/, '').trim();
                if (!h) return;
                // Explicit user action: drop any cached resolve failure and scan fresh.
                delete Core._queryIdMisses['UserByScreenName'];
                this.fetchProfileStats(h, true);
            };
            ['tpm-d-followers', 'tpm-d-following', 'tpm-d-age'].forEach(id => {
                UI.el(id).addEventListener('input', () => this.calculate());
            });
            ['tpm-d-verified', 'tpm-d-device', 'tpm-d-restricted'].forEach(id => {
                UI.el(id).addEventListener('change', () => this.calculate());
            });
        },

        // Fill only blank fields, so we never clobber values the user typed.
        setIfEmpty(id, val) {
            if (val == null || val === '') return;
            const el = UI.el(id);
            if (el && el.value.trim() === '') el.value = val;
        },

        // Visible lookup status — lookup failures must never be silent again.
        dstatus(text) {
            const el = UI.el('tpm-d-status');
            if (el) el.textContent = text || '';
        },

        // Read what the page DOM exposes, then fetch authoritative numbers from
        // the API (works from any page and reliably provides account age + the
        // verified flag the score needs).
        autofill() {
            const grab = (suffixes) => {
                for (const sfx of suffixes) {
                    const a = document.querySelector(`a[href$="${sfx}"]`);
                    if (a) {
                        const strong = a.querySelector('span');
                        const n = Core.parseCount(a.getAttribute('title') || (strong && strong.textContent) || a.textContent);
                        if (n != null) return n;
                    }
                }
                return null;
            };
            this.setIfEmpty('tpm-d-followers', grab(['/verified_followers', '/followers']));
            this.setIfEmpty('tpm-d-following', grab(['/following']));
            if (Core.username && !Core.isReservedName(Core.username)) this.setIfEmpty('tpm-d-handle', '@' + Core.username);

            this.calculate();
            this.fetchProfileStats();
        },

        // Authoritative profile stats via UserByScreenName for `handle` (defaults
        // to the logged-in user). `force` re-runs even after a prior fetch and
        // overwrites fields (used by the "Look up" button). Fails quietly.
        async fetchProfileStats(handle, force = false) {
            const screen_name = (handle || Core.username || '').replace(/^@/, '').trim();
            if (!screen_name || Core.isReservedName(screen_name)) {
                this.dstatus('Waiting for your X username to resolve…');
                return;
            }
            if (!force && (this._statsFetched || this._statsFetching)) return;
            this._statsFetching = true;
            try {
                const variables = JSON.stringify({ screen_name, withSafetyModeUserFields: true });
                const features = JSON.stringify({
                    hidden_profile_subscriptions_enabled: true, rweb_tipjar_consumption_enabled: true,
                    responsive_web_graphql_exclude_directive_enabled: true, verified_phone_label_enabled: false,
                    subscriptions_verification_info_is_identity_verified_enabled: true,
                    subscriptions_verification_info_verified_since_enabled: true, highlights_tweets_tab_ui_enabled: true,
                    responsive_web_twitter_article_notes_tab_enabled: true, subscriptions_feature_can_gift_premium: true,
                    creator_subscriptions_tweet_preview_api_enabled: true,
                    responsive_web_graphql_skip_user_profile_image_extensions_enabled: false,
                    responsive_web_graphql_timeline_navigation_enabled: true
                });
                // At userscript boot X's api bundle (which holds the query ids) is
                // often still loading — resolve, give it a moment, resolve again.
                let queryId = await Core.resolveQueryId('UserByScreenName');
                if (!queryId) {
                    this.dstatus('Still locating X’s profile lookup in the page bundles…');
                    await Core.sleep(3000);
                    delete Core._queryIdMisses['UserByScreenName'];
                    queryId = await Core.resolveQueryId('UserByScreenName');
                }
                if (!queryId) {
                    this.dstatus('Could not resolve X’s profile lookup yet. Open any X profile once, then press Look up.');
                    console.log('[TPM] Could not resolve the UserByScreenName query id from the page bundles.');
                    return;
                }
                const url = `${Core.baseUrl}/i/api/graphql/${queryId}/UserByScreenName?` + new URLSearchParams({ variables, features });
                const res = await fetch(url, {
                    headers: Core.apiHeaders(), referrer: `${Core.baseUrl}/${screen_name}`,
                    referrerPolicy: 'strict-origin-when-cross-origin', method: 'GET', mode: 'cors',
                    credentials: 'include', signal: AbortSignal.timeout(8000)
                });
                if (res.status !== 200) {
                    // A stale sniffed/cached id can 404; drop it so the next try re-resolves.
                    if (res.status === 404) { delete Core._queryIds['UserByScreenName']; delete Core._queryIdMisses['UserByScreenName']; }
                    this.dstatus(`Profile fetch failed (HTTP ${res.status}) for @${screen_name}.${res.status === 404 ? ' The lookup id rotated — retry in a moment.' : ''}`);
                    console.log(`[TPM] Profile fetch failed (HTTP ${res.status}) for @${screen_name}.`);
                    return;
                }
                const result = (await res.json())?.data?.user?.result;
                const lg = result?.legacy;
                if (!lg) { this.dstatus(`X returned no profile data for @${screen_name} (suspended, protected, or renamed?).`); return; }
                const set = (id, v) => { const el = UI.el(id); if (el && v != null) el.value = v; };
                const fill = force ? set : ((id, v) => this.setIfEmpty(id, v));
                fill('tpm-d-followers', lg.followers_count);
                fill('tpm-d-following', lg.friends_count);
                if (lg.created_at) {
                    const days = Math.max(0, Math.round((Date.now() - new Date(lg.created_at).getTime()) / 86400000));
                    fill('tpm-d-age', days);
                }
                // The 2023 mass formula's isVerified is LEGACY verification only
                // (safety.verified), NOT X Premium / blue. Reproduce that exactly.
                UI.el('tpm-d-verified').checked = !!lg.verified;
                this.dstatus('');
                if (!force) this._statsFetched = true;
                this.calculate();
            } catch (e) {
                this.dstatus(`Profile fetch error: ${(e && e.message) || e}`);
                console.log('[TPM] Profile fetch error:', e);
            } finally {
                this._statsFetching = false;
            }
        },

        // Exact reproduction of the 2023 open-source tweepcred maths:
        //   UserMass.getUserMass  +  Reputation.adjustReputationsPostCalculation
        // Constants and operators are copied verbatim from the source. The only
        // stage we cannot run is the global PageRank that consumes this mass, so
        // the number shown is the per-user mass/prior, not the PageRank output.
        computeMass(inp) {
            // --- UserMass.scala constants ---
            const deviceWeightAdditive = 0.5;
            const restrictedWeightMultiplicative = 0.1;
            const threshAbsNumFriendsUMass = 500;
            const threshFriendsToFollowersRatioUMass = 0.6;
            const constDivUMass = 5.0;

            const { followers, following, ageDays, verified, suspended, validDevice, restricted } = inp;
            const steps = [];

            let mass;
            if (suspended) {
                mass = 0;
                steps.push({ k: 'Suspended', v: 'mass = 0' });
            } else if (verified) {
                mass = 100;
                steps.push({ k: 'Legacy verified', v: 'mass = 100' });
            } else {
                let score = deviceWeightAdditive * 0.1 + (validDevice ? deviceWeightAdditive : 0);
                steps.push({ k: 'Base (device)', v: `${(score * 100).toFixed(0)} / 100` });
                const normalizedAge = ageDays > 30 ? 1.0 : Math.min(1.0, Math.log(1.0 + ageDays / 15.0));
                score *= normalizedAge;
                if (ageDays <= 30) steps.push({ k: 'New-account deboost', v: `×${normalizedAge.toFixed(2)} (age ${ageDays}d)` });
                if (score < 0.01) score = 0.01;
                if (restricted) { score *= restrictedWeightMultiplicative; steps.push({ k: 'Restricted', v: '×0.1' }); }
                score = Math.max(Math.min(score, 1.0), 0);
                score *= 100;
                mass = score;
            }

            // Ratio penalty from UserMass (following > 500 AND friends/followers > 0.6)
            const ratio = (1.0 + following) / (1.0 + followers);
            if (following > threshAbsNumFriendsUMass && ratio > threshFriendsToFollowersRatioUMass) {
                const div = Math.exp(constDivUMass * (ratio - threshFriendsToFollowersRatioUMass));
                mass = mass / div;
                steps.push({ k: 'Following-ratio penalty', v: `÷${div.toFixed(2)} (ratio ${ratio.toFixed(2)})` });
            }

            // Reputation.adjustReputationsPostCalculation (following > 2500)
            const threshAbsNumFriendsReps = 2500;
            const maxDivFactorReps = 50;
            if (following > threshAbsNumFriendsReps) {
                const divFactor = Math.exp(3.0 * (ratio - 0.6) * Math.log(Math.log(following)));
                const denom = Math.max(Math.min(divFactor, maxDivFactorReps), 1.0);
                mass = mass / denom;
                steps.push({ k: 'High-following penalty', v: `÷${denom.toFixed(2)} (>2500 following)` });
            }

            return { score: Math.max(0, Math.min(100, Math.round(mass))), ratio, steps };
        },

        calculate() {
            const followers = parseInt(UI.el('tpm-d-followers').value, 10);
            const following = parseInt(UI.el('tpm-d-following').value, 10);
            if (isNaN(followers) || isNaN(following)) return;
            const ageDays = parseInt(UI.el('tpm-d-age').value, 10);

            const inp = {
                followers, following,
                ageDays: isNaN(ageDays) ? 9999 : ageDays,   // unknown age => past the 30-day cliff
                verified: UI.el('tpm-d-verified').checked,
                suspended: false,
                validDevice: UI.el('tpm-d-device').checked,
                restricted: UI.el('tpm-d-restricted').checked
            };

            const { score, ratio, steps } = this.computeMass(inp);
            this.paint(score, steps, { followers, following, ratio, verified: inp.verified, validDevice: inp.validDevice });
        },

        paint(score, steps, ctx) {
            const color = score >= 65 ? 'var(--ok)' : score >= 45 ? 'var(--warn)' : 'var(--danger)';
            const num = UI.el('tpm-score-num');
            num.textContent = score;
            num.style.color = color;
            const fill = UI.el('tpm-score-fill');
            fill.style.width = `${score}%`;
            fill.style.background = color;
            UI.el('tpm-score-label').innerHTML = score >= 65
                ? '✅ At/above ~65 — all your tweets stay eligible for ranking'
                : '⚠️ Below ~65 — the legacy search filter cut eligible tweets to ~3';

            // Show the actual computation steps from the source formula.
            UI.el('tpm-factors').innerHTML = steps.map(st => `
              <div class="tpm-factor-top" style="margin:6px 0">
                <span>${Core.escapeHtml(st.k)}</span><span>${Core.escapeHtml(st.v)}</span>
              </div>`).join('') || '<div class="tpm-note">No adjustments applied.</div>';

            this.recommend(score, ctx);
        },

        recommend(score, ctx) {
            const recs = [];
            const { followers, following, ratio, verified, validDevice } = ctx;

            // The two real ratio penalties: > 0.6 friends/followers with > 500 following.
            if (following > 500 && ratio > 0.6) {
                // following count that brings the ratio back to the 0.6 threshold
                const targetFollowing = Math.max(0, Math.floor(0.6 * (1 + followers) - 1));
                const cut = Math.max(0, following - targetFollowing);
                recs.push(`The follow-ratio penalty is active (following/followers = ${ratio.toFixed(2)} &gt; 0.6 with 500+ following). Unfollowing about <strong>${cut.toLocaleString()}</strong> non-followers clears it. <a href="#" id="tpm-rec-unfollow">Open the Unfollow tool →</a>`);
            } else if (following > 2500) {
                recs.push(`You follow over 2,500 accounts, which triggers the high-following reputation penalty. Trimming non-followers reduces it. <a href="#" id="tpm-rec-unfollow">Open the Unfollow tool →</a>`);
            }

            if (!verified) {
                recs.push('In the legacy formula a <strong>legacy-verified</strong> account (the old manually-granted blue check) has its mass set to <strong>100</strong> outright, the single biggest lever in this model. Note: X Premium / blue is a different flag and did not feed this formula.');
            }
            if (!validDevice) {
                recs.push('Verify a phone / use a valid device. Without one the base mass drops from 55 to 5 before any other factor.');
            }

            // Honest note on what tweethunter adds that the source does NOT.
            recs.push('Note: third-party calculators also weight <em>engagement</em> and <em>posting consistency</em>. Those aren\'t in X\'s open-source mass formula (they belong to the live ranking model), so they\'re excluded from this exact-reproduction score but still matter in practice.');

            if (score >= 65 && !(following > 500 && ratio > 0.6)) {
                recs.unshift('You\'re at or above the ~65 line. Keep your follow ratio healthy to stay there.');
            }

            UI.el('tpm-recs').innerHTML = recs.map(r => `<li>${r}</li>`).join('');
            const ru = UI.el('tpm-rec-unfollow'); if (ru) ru.onclick = (e) => { e.preventDefault(); UI.switchTab('unfollow'); };
        }
    };

/* ---- src/modules/unfollow.js ---- */
/**
 * @module unfollow
 * @see docs/modules/unfollow.md
 */
    /* ===================================================================== *
     *  UNFOLLOW — repair your ratio. Engine ported from Mass-Unfollower,      *
     *  unified one-shot + continuous, plus audit (dry-run) and a whitelist.   *
     * ===================================================================== */
    const Unfollow = {
        running: false,
        paused: false,
        stop: false,
        firstShow: true,
        log: [],

        onShow() {
            if (this.firstShow) { this.render(); this.firstShow = false; }
            this.checkLocation();
        },

        render() {
            const s = Core.store;
            UI.el('tpm-pane-unfollow').innerHTML = `
              <div id="tpm-unf-locwarn"></div>
              <div class="tpm-stats">
                <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-unf-done">0</div><div class="tpm-stat-l">Unfollowed</div></div>
                <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-unf-skip">0</div><div class="tpm-stat-l">Skipped</div></div>
                <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-unf-left">0</div><div class="tpm-stat-l">Left in batch</div></div>
              </div>
              <div class="tpm-now" id="tpm-unf-now">Idle — go to your <strong>Following</strong> page, then Start.</div>

              <div class="tpm-section">
                <h4>Settings</h4>
                <div class="tpm-row">
                  <div><label class="tpm-label">Batch size</label><input id="tpm-unf-max" type="number" class="tpm-input" value="${s.get('unf.max', 190)}" min="1" max="500"></div>
                  <div><label class="tpm-label">Min delay (s)</label><input id="tpm-unf-mind" type="number" class="tpm-input" value="${s.get('unf.mind', 3)}" min="0" max="120"></div>
                  <div><label class="tpm-label">Max delay (s)</label><input id="tpm-unf-maxd" type="number" class="tpm-input" value="${s.get('unf.maxd', 35)}" min="2" max="180"></div>
                </div>
                <label class="tpm-check"><input type="checkbox" id="tpm-unf-cont" ${s.get('unf.cont', false) ? 'checked' : ''}> Continuous mode — keep going in batches with a cooldown (instead of stopping at one batch)</label>
                <div class="tpm-row" id="tpm-unf-cooldownrow" style="${s.get('unf.cont', false) ? '' : 'display:none'}">
                  <div><label class="tpm-label">Cooldown min (min)</label><input id="tpm-unf-cmin" type="number" class="tpm-input" value="${s.get('unf.cmin', 15)}" min="1" max="120"></div>
                  <div><label class="tpm-label">Cooldown max (min)</label><input id="tpm-unf-cmax" type="number" class="tpm-input" value="${s.get('unf.cmax', 20)}" min="1" max="180"></div>
                </div>
                <label class="tpm-check"><input type="checkbox" id="tpm-unf-mutuals" ${s.get('unf.mutuals', true) ? 'checked' : ''}> Preserve mutual followers (never unfollow people who follow you back)</label>
                <label class="tpm-check"><input type="checkbox" id="tpm-unf-private" ${s.get('unf.private', true) ? 'checked' : ''}> Skip private / locked accounts</label>
              </div>

              <div class="tpm-section">
                <h4>Whitelist — never unfollow these</h4>
                <p>One @handle per line (or comma-separated). Saved on this browser.</p>
                <textarea id="tpm-unf-white" class="tpm-input" placeholder="@friend&#10;@favbrand">${Core.escapeHtml((s.get('unf.white', []) || []).map(u => '@' + u).join('\n'))}</textarea>
              </div>

              <div class="tpm-section">
                <h4>Posted-word filter (X search)</h4>
                <p>For each followed account, runs an X search (<code>from:user "term"</code>) to check whether they have ever <strong>posted</strong> any of your terms, then either protects or targets them. Built for research groups studying the prevalence of hate speech and other content on the platform. Each term is matched as an exact phrase; comma- or newline-separated. One search request per account (counts toward rate limits).</p>
                <label class="tpm-label" for="tpm-unf-kw">Terms to search for in their posts</label>
                <textarea id="tpm-unf-kw" class="tpm-input" placeholder="term one, term two">${Core.escapeHtml(s.get('unf.kw', '') || '')}</textarea>
                <label class="tpm-label" for="tpm-unf-kw-action">When an account has posted a term</label>
                <select id="tpm-unf-kw-action" class="tpm-input">
                  <option value="off">Do nothing (filter off)</option>
                  <option value="protect">Protect — never unfollow accounts that posted it</option>
                  <option value="target">Target — only act on accounts that posted it</option>
                </select>
                <p class="tpm-note" id="tpm-unf-kw-note"></p>
              </div>

              <div class="tpm-btns">
                <button class="tpm-btn tpm-btn-ghost" id="tpm-unf-audit" type="button">Scan only (audit)</button>
                <button class="tpm-btn tpm-btn-primary" id="tpm-unf-start" type="button">Start unfollowing</button>
              </div>
              <div class="tpm-btns">
                <button class="tpm-btn tpm-btn-ghost" id="tpm-unf-report" type="button">Scan for posted words → report (no unfollows)</button>
              </div>
              <div id="tpm-unf-report-out" style="display:none"></div>
              <div class="tpm-btns" id="tpm-unf-live" style="display:none">
                <button class="tpm-btn tpm-btn-warn" id="tpm-unf-pause" type="button">Pause</button>
                <button class="tpm-btn tpm-btn-danger" id="tpm-unf-stop" type="button">Stop</button>
              </div>
              <div class="tpm-status idle" id="tpm-unf-status">Idle</div>
              <div class="tpm-note">Stays under X rate limits with human-like random delays. Continuous high-volume unfollowing is exactly what X's automation detection watches for — stop for the day if you see a "you're doing that too much" warning.</div>`;

            UI.el('tpm-unf-cont').addEventListener('change', (e) => {
                UI.el('tpm-unf-cooldownrow').style.display = e.target.checked ? '' : 'none';
            });
            // Restore saved keyword action and keep a plain-language note in sync.
            const kwAction = UI.el('tpm-unf-kw-action');
            kwAction.value = s.get('unf.kwAction', 'off');
            const kwNote = () => {
                const map = {
                    off: 'Filter is off. The terms field is ignored.',
                    protect: 'Accounts that have posted a term will be SKIPPED (kept). Use this to preserve a study cohort while you trim everyone else.',
                    target: 'ONLY accounts that have posted a term will be unfollowed. Others are skipped. Use Scan only to preview the matched set before acting.'
                };
                UI.el('tpm-unf-kw-note').textContent = map[kwAction.value] || '';
            };
            kwAction.addEventListener('change', kwNote);
            kwNote();
            UI.el('tpm-unf-audit').onclick = () => this.audit();
            UI.el('tpm-unf-start').onclick = () => this.start();
            UI.el('tpm-unf-report').onclick = () => this.reportPostedWords();
            UI.el('tpm-unf-pause').onclick = () => this.togglePause();
            UI.el('tpm-unf-stop').onclick = () => { this.stop = true; this.setStatus('stop', '🔴 Stopping…'); };
        },

        checkLocation() {
            const onList = /\/(following|followers|verified_followers)\b/.test(location.pathname) ||
                document.querySelector('[data-testid="UserCell"]');
            const box = UI.el('tpm-unf-locwarn');
            if (!box) return;
            box.innerHTML = onList ? '' :
                `<div class="tpm-warn-box">Open your <strong>Following</strong> list first: go to your profile → <em>Following</em> (URL ends in <code>/following</code>). The unfollow engine works on whatever follow-list is open.</div>`;
        },

        readSettings() {
            const v = (id, d) => { const n = parseFloat(UI.el(id).value); return isNaN(n) ? d : n; };
            this.MAX = v('tpm-unf-max', 190);
            this.MIN_DELAY = v('tpm-unf-mind', 3) * 1000;
            this.MAX_DELAY = v('tpm-unf-maxd', 35) * 1000;
            this.continuous = UI.el('tpm-unf-cont').checked;
            this.PAUSE_MIN = v('tpm-unf-cmin', 15) * 60000;
            this.PAUSE_MAX = v('tpm-unf-cmax', 20) * 60000;
            this.skipPrivate = UI.el('tpm-unf-private').checked;
            this.preserveMutuals = UI.el('tpm-unf-mutuals').checked;
            this.whitelist = new Set(
                (UI.el('tpm-unf-white').value.match(/[A-Za-z0-9_]+/g) || []).map(u => u.toLowerCase())
            );

            // Posted-word filter (X search): terms the account may have posted.
            const kwRaw = UI.el('tpm-unf-kw').value || '';
            this.kwAction = UI.el('tpm-unf-kw-action').value;        // off | protect | target
            this.kwTerms = kwRaw.split(/[\n,]+/).map(t => t.trim()).filter(Boolean);
            if (this.kwAction !== 'off' && this.kwTerms.length === 0) this.kwAction = 'off';

            const s = Core.store;
            s.set('unf.max', this.MAX); s.set('unf.mind', this.MIN_DELAY / 1000); s.set('unf.maxd', this.MAX_DELAY / 1000);
            s.set('unf.cont', this.continuous); s.set('unf.cmin', this.PAUSE_MIN / 60000); s.set('unf.cmax', this.PAUSE_MAX / 60000);
            s.set('unf.private', this.skipPrivate); s.set('unf.mutuals', this.preserveMutuals); s.set('unf.white', [...this.whitelist]);
            s.set('unf.kw', kwRaw); s.set('unf.kwAction', UI.el('tpm-unf-kw-action').value);
        },

        // Has this account ever POSTED one of the configured terms? Runs an X
        // search (from:user "term"). Returns true/false, or null if the search
        // couldn't be completed (so the caller can skip rather than mis-act).
        async keywordMatches(_cell, username) {
            if (!this.kwTerms || !this.kwTerms.length) return false;
            const r = await Core.userPostedTerm(username, this.kwTerms);
            if (r == null) return null;
            return r.matched;
        },

        setStatus(kind, text) {
            const el = UI.el('tpm-unf-status');
            el.className = 'tpm-status ' + kind;
            el.textContent = text;
        },
        setNow(html) { UI.el('tpm-unf-now').innerHTML = html; },
        setStats(done, skip, leftInBatch) {
            UI.el('tpm-unf-done').textContent = done;
            UI.el('tpm-unf-skip').textContent = skip;
            UI.el('tpm-unf-left').textContent = leftInBatch;
        },

        logAction(username, action, reason = '') {
            const time = new Date().toLocaleTimeString();
            this.log.push({ time, username, action, reason });
            const colors = { unfollowed: 'color:green;font-weight:bold', skipped: 'color:orange', error: 'color:red;font-weight:bold' };
            console.log(`%c[${time}] ${action.toUpperCase()} - @${username} ${reason}`, colors[action] || '');
        },

        async waitWhilePaused() { while (this.paused && !this.stop) await Core.sleep(500); },

        togglePause() {
            this.paused = !this.paused;
            UI.el('tpm-unf-pause').textContent = this.paused ? 'Resume' : 'Pause';
            this.setStatus(this.paused ? 'pause' : 'run', this.paused ? '🟡 Paused' : '🟢 Running…');
        },

        // Dry run: scroll the whole list and tally categories without unfollowing.
        async audit() {
            if (this.running) return;
            this.readSettings();
            this.running = true; this.stop = false;
            UI.el('tpm-unf-audit').disabled = true;
            UI.el('tpm-unf-start').disabled = true;
            UI.el('tpm-unf-live').style.display = 'flex';
            this.setStatus('run', '🔍 Auditing (no unfollows)…');

            const kwOn = this.kwAction && this.kwAction !== 'off';
            const seen = new Set();
            const kwMatches = [];
            let mutuals = 0, nonFollowers = 0, privates = 0, whitelisted = 0, kwMatched = 0, empty = 0;
            while (!this.stop && empty < 15) {
                await this.waitWhilePaused();
                const cells = Array.from(document.querySelectorAll('[data-testid="UserCell"], [data-testid="cellInnerDiv"]'));
                let found = false;
                for (const cell of cells) {
                    if (!cell.querySelector('a[href^="/"]')) continue;
                    const u = Follow.getUsername(cell);
                    if (u === 'unknown' || seen.has(u)) continue;
                    seen.add(u); found = true;
                    const uc = cell.matches?.('[data-testid="UserCell"]') ? cell
                        : (cell.querySelector?.('[data-testid="UserCell"]') || cell);
                    if (this.whitelist.has(u.toLowerCase())) whitelisted++;
                    else if (Follow.isMutual(uc)) mutuals++;
                    else if (Follow.isPrivate(uc)) privates++;
                    else nonFollowers++;
                    // Tally keyword matches when the filter is configured.
                    if (kwOn) {
                        uc.scrollIntoView({ block: 'center', behavior: 'instant' });
                        const m = await this.keywordMatches(uc, u);
                        if (m === true) { kwMatched++; kwMatches.push(u); console.log(`%c[audit] keyword match: @${u}`, 'color:#f4212e'); }
                    }
                    this.setStats(nonFollowers, mutuals + privates + whitelisted, kwOn ? kwMatched : '—');
                    this.setNow(`Scanned <strong>${seen.size}</strong>${kwOn ? ` · <strong>${kwMatched}</strong> keyword matches` : ''}…`);
                }
                if (!found) {
                    empty++;
                    const last = cells[cells.length - 1];
                    if (last) last.scrollIntoView({ block: 'end', behavior: 'instant' });
                    window.scrollBy(0, 800);
                    await Core.sleep(2000);
                } else { empty = 0; }
            }

            this.setStatus('idle', '✅ Audit complete');
            const kwLine = kwOn ? ` · <strong>${kwMatched}</strong> keyword matches` : '';
            this.setNow(`<strong>${seen.size}</strong> scanned · <strong>${nonFollowers}</strong> non-followers · ${mutuals} mutuals · ${privates} private · ${whitelisted} whitelisted${kwLine}`);
            console.table({ scanned: seen.size, nonFollowers, mutuals, privates, whitelisted, keywordMatches: kwMatched });
            if (kwOn) console.log('Keyword-matched accounts:', kwMatches);
            this.finishUI();
        },

        // Report-only scan: walk the open follow list, search each account's posts
        // for the configured terms, and produce a downloadable list of positive
        // hits. Never unfollows anyone. For research/monitoring use.
        async reportPostedWords() {
            if (this.running) return;
            this.readSettings();
            if (!this.kwTerms || !this.kwTerms.length) {
                this.setStatus('stop', '⚠️ Enter at least one term first');
                return;
            }
            this.running = true; this.stop = false; this.paused = false;
            UI.el('tpm-unf-audit').disabled = true;
            UI.el('tpm-unf-start').disabled = true;
            UI.el('tpm-unf-report').disabled = true;
            UI.el('tpm-unf-live').style.display = 'flex';
            UI.el('tpm-unf-pause').textContent = 'Pause';
            this.setStatus('run', '🔍 Searching posts (no unfollows)…');
            console.log(`%c[report] Searching followed accounts for: ${this.kwTerms.join(', ')}`, 'color:#1d9bf0;font-weight:bold');

            const seen = new Set();
            const hits = [];          // { username, term, scannedAt }
            let scanned = 0, errors = 0, empty = 0;
            const MAX_EMPTY = 15;

            while (!this.stop && empty < MAX_EMPTY) {
                await this.waitWhilePaused();
                if (this.stop) break;
                const cells = Array.from(document.querySelectorAll('[data-testid="UserCell"], [data-testid="cellInnerDiv"]'));
                let found = false;
                for (const cell of cells) {
                    if (this.stop) break;
                    await this.waitWhilePaused();
                    if (!cell.querySelector('a[href^="/"]')) continue;
                    const u = Follow.getUsername(cell);
                    if (u === 'unknown' || seen.has(u)) continue;
                    seen.add(u); found = true; scanned++;

                    const r = await Core.userPostedTerm(u, this.kwTerms);
                    if (r == null) {
                        errors++;
                        this.logAction(u, 'error', 'Post search failed');
                    } else if (r.matched) {
                        hits.push({ username: u, term: r.term, time: new Date().toISOString() });
                        console.log(`%c[report] HIT @${u} — posted "${r.term}"`, 'color:#f4212e;font-weight:bold');
                    }
                    this.setStats(hits.length, scanned, errors);
                    this.setNow(`Searched <strong>${scanned}</strong> · <strong>${hits.length}</strong> hits${errors ? ` · ${errors} errors` : ''}`);

                    // Pace search requests to stay under the rate limit.
                    await Core.sleep(this.MIN_DELAY);
                }
                if (!found) {
                    empty++;
                    const last = cells[cells.length - 1];
                    if (last) last.scrollIntoView({ block: 'end', behavior: 'instant' });
                    window.scrollBy(0, 800);
                    await Core.sleep(2000);
                } else { empty = 0; }
            }

            this.setStatus('idle', '✅ Report complete');
            this.setNow(`Searched <strong>${scanned}</strong> accounts · <strong>${hits.length}</strong> posted a term${errors ? ` · ${errors} errors` : ''}`);
            console.table(hits);
            this.renderReport(hits, scanned, errors);
            this.finishUI();
            UI.el('tpm-unf-report').disabled = false;
        },

        // Render the hit list with copy + CSV/JSON download (no network, no deletes).
        renderReport(hits, scanned, errors) {
            const out = UI.el('tpm-unf-report-out');
            if (!out) return;
            if (!hits.length) {
                out.style.display = '';
                out.innerHTML = `<div class="tpm-section"><h4>Report</h4><p>Searched ${scanned} accounts. No account posted any of the terms${errors ? ` (${errors} could not be searched)` : ''}.</p></div>`;
                return;
            }
            const rows = hits.map(h => `<li>@${Core.escapeHtml(h.username)} <span style="color:var(--muted)">— "${Core.escapeHtml(h.term)}"</span></li>`).join('');
            out.style.display = '';
            out.innerHTML = `
              <div class="tpm-section">
                <h4>Positive hits (${hits.length})</h4>
                <p>Searched ${scanned} accounts${errors ? `, ${errors} could not be searched` : ''}. No accounts were unfollowed.</p>
                <ul style="max-height:200px;overflow:auto;margin:0 0 10px;padding-left:18px">${rows}</ul>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-unf-report-copy" type="button">Copy handles</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-unf-report-csv" type="button">Download CSV</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-unf-report-json" type="button">Download JSON</button>
                </div>
              </div>`;

            const download = (name, type, content) => {
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([content], { type }));
                a.download = name; a.click();
                setTimeout(() => URL.revokeObjectURL(a.href), 2000);
            };
            UI.el('tpm-unf-report-copy').onclick = () => {
                navigator.clipboard?.writeText(hits.map(h => '@' + h.username).join('\n'));
                this.setStatus('idle', '📋 Handles copied');
            };
            UI.el('tpm-unf-report-csv').onclick = () => {
                const csv = 'username,matched_term,scanned_at\n' +
                    hits.map(h => `${h.username},"${(h.term || '').replace(/"/g, '""')}",${h.time}`).join('\n');
                download('posted-word-hits.csv', 'text/csv', csv);
            };
            UI.el('tpm-unf-report-json').onclick = () => {
                download('posted-word-hits.json', 'application/json', JSON.stringify(hits, null, 2));
            };
        },

        async start() {
            if (this.running) return;
            this.readSettings();
            this.running = true; this.stop = false; this.paused = false;
            UI.el('tpm-unf-audit').disabled = true;
            UI.el('tpm-unf-start').disabled = true;
            UI.el('tpm-unf-live').style.display = 'flex';
            UI.el('tpm-unf-pause').textContent = 'Pause';
            this.setStatus('run', '🟢 Running…');
            console.log('%c[Tweepcred Manager] Unfollow started', 'color:#1d9bf0;font-weight:bold');

            let total = 0, batchCount = 0, skipped = 0, batchNum = 1;
            const processed = new Set();
            let emptyScrolls = 0;
            // ~30s of patience: X's lazy list loader stalls when rate-limited, and
            // quitting after 10s ends runs early.
            const MAX_EMPTY = 15;
            this.setStats(0, 0, this.MAX);

            const randomDelay = () => this.MIN_DELAY + Math.floor(Math.random() * (this.MAX_DELAY - this.MIN_DELAY));

            while (!this.stop) {
                await this.waitWhilePaused();
                if (this.stop) break;

                if (batchCount >= this.MAX) {
                    if (!this.continuous) break;            // one-shot: stop at the cap
                    await this.cooldown(total);              // continuous: long cooldown
                    if (this.stop) break;
                    batchCount = 0; batchNum++;
                    console.log(`%c🔄 Batch #${batchNum}…`, 'color:#1d9bf0;font-weight:bold');
                    continue;
                }

                const cells = Array.from(document.querySelectorAll('[data-testid="UserCell"], [data-testid="cellInnerDiv"]'));
                let target = null, username = null;
                for (const cell of cells) {
                    if (!cell.querySelector('a[href^="/"]')) continue;
                    const u = Follow.getUsername(cell);
                    if (u === 'unknown' || processed.has(u)) continue;
                    target = cell; username = u; break;
                }

                if (!target) {
                    const last = cells[cells.length - 1];
                    if (last) last.scrollIntoView({ block: 'end', behavior: 'instant' });
                    window.scrollBy(0, 800);
                    await Core.sleep(2000);
                    if (++emptyScrolls >= MAX_EMPTY) { console.log('🏁 End of list.'); break; }
                    continue;
                }
                emptyScrolls = 0;
                processed.add(username);

                // Resolve to the precise UserCell so the "Follows you" badge, the
                // username and the unfollow button all belong to the SAME account.
                // The matched node is frequently the outer cellInnerDiv wrapper.
                const cell = target.matches?.('[data-testid="UserCell"]')
                    ? target
                    : (target.querySelector?.('[data-testid="UserCell"]') || target);

                const lower = username.toLowerCase();
                if (this.whitelist.has(lower)) {
                    this.logAction(username, 'skipped', 'Whitelisted'); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount); continue;
                }

                // Render the cell BEFORE testing mutual/private status. X lazily
                // renders the "Follows you" badge, so checking an off-screen row
                // can miss it and unfollow a mutual. Scroll first, let it paint,
                // THEN check. (This ordering was the mutual-preservation bug.)
                cell.scrollIntoView({ block: 'center', behavior: 'instant' });
                await Core.sleep(400);

                if (this.preserveMutuals && Follow.isMutual(cell)) {
                    this.logAction(username, 'skipped', 'Mutual follow'); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount); continue;
                }
                if (this.skipPrivate && Follow.isPrivate(cell)) {
                    this.logAction(username, 'skipped', 'Private/locked'); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount); continue;
                }

                // Posted-word filter: protect (skip those who posted it) or target
                // (skip those who didn't). Runs an X search per account.
                if (this.kwAction && this.kwAction !== 'off') {
                    this.setNow(`Searching @${Core.escapeHtml(username)}'s posts…`);
                    const matched = await this.keywordMatches(cell, username);
                    if (matched === null) {
                        this.logAction(username, 'skipped', 'Post search failed (could not query)'); skipped++;
                        this.setStats(total, skipped, this.MAX - batchCount); continue;
                    }
                    if (this.kwAction === 'protect' && matched) {
                        this.logAction(username, 'skipped', 'Posted a term — protected'); skipped++;
                        this.setStats(total, skipped, this.MAX - batchCount); continue;
                    }
                    if (this.kwAction === 'target' && !matched) {
                        this.logAction(username, 'skipped', 'Never posted a term (target mode)'); skipped++;
                        this.setStats(total, skipped, this.MAX - batchCount); continue;
                    }
                }

                const btn = Follow.findUnfollowButton(cell);
                if (!btn) {
                    this.logAction(username, 'skipped', 'No unfollow button'); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount); continue;
                }

                // Final safety net: re-check on the live element immediately before
                // the click, in case the virtualized list re-rendered the row. A
                // mutual must never be unfollowed while preservation is on.
                if (this.preserveMutuals && Follow.isMutual(cell)) {
                    this.logAction(username, 'skipped', 'Mutual follow (guard)'); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount); continue;
                }

                this.setNow(`Processing <strong>@${Core.escapeHtml(username)}</strong>`);
                try {
                    const anchors = Array.from(cell.querySelectorAll('a'));
                    const blockNav = (e) => e.preventDefault();
                    anchors.forEach(a => a.addEventListener('click', blockNav, true));
                    btn.click();
                    await Core.sleep(100);
                    anchors.forEach(a => a.removeEventListener('click', blockNav, true));

                    const confirmBtn = await Follow.waitConfirm();
                    if (confirmBtn) { confirmBtn.click(); this.logAction(username, 'unfollowed'); }
                    else this.logAction(username, 'skipped', 'No confirm dialog — assuming unfollowed');
                    total++; batchCount++;
                    this.setStats(total, skipped, this.MAX - batchCount);
                } catch (err) {
                    this.logAction(username, 'error', err.message); skipped++;
                    this.setStats(total, skipped, this.MAX - batchCount);
                }

                if (this.stop) break;
                await this.waitWhilePaused();
                const d = randomDelay();
                this.setNow(`⏳ Waiting ${Math.round(d / 1000)}s…`);
                await Core.sleep(d);
            }

            this.setStatus('stop', '✅ Complete');
            this.setNow(`🎉 Done — unfollowed <strong>${total}</strong>, skipped ${skipped}.`);
            console.log(`%c=== UNFOLLOW COMPLETE === total ${total}, skipped ${skipped}, batches ${batchNum}`, 'color:#1d9bf0;font-weight:bold');
            console.table(this.log);
            this.finishUI();
        },

        async cooldown(totalSoFar) {
            const ms = this.PAUSE_MIN + Math.floor(Math.random() * Math.max(0, this.PAUSE_MAX - this.PAUSE_MIN));
            const endAt = Date.now() + ms;
            this.setStatus('pause', '😴 Cooling down…');
            console.log(`%c😴 Batch done (total ${totalSoFar}). Cooldown ${Math.round(ms / 60000)} min…`, 'color:#f7931a;font-weight:bold');
            while (Date.now() < endAt && !this.stop) {
                if (this.paused) { await Core.sleep(500); continue; }
                const rem = endAt - Date.now();
                const mins = Math.floor(rem / 60000), secs = Math.floor((rem % 60000) / 1000);
                this.setNow(`😴 Next batch in <strong>${mins}:${String(secs).padStart(2, '0')}</strong>`);
                await Core.sleep(1000);
            }
            if (!this.stop) this.setStatus('run', '🟢 Running…');
        },

        finishUI() {
            this.running = false;
            UI.el('tpm-unf-audit').disabled = false;
            UI.el('tpm-unf-start').disabled = false;
            const rep = UI.el('tpm-unf-report'); if (rep) rep.disabled = false;
            UI.el('tpm-unf-live').style.display = 'none';
        }
    };

/* ---- src/modules/cleanup.js ---- */
/**
 * @module cleanup
 * @see docs/modules/cleanup.md
 */
    /* ===================================================================== *
     *  CLEANUP — delete tweets / likes / DMs. Engine ported from TweetXer.    *
     * ===================================================================== */
    const Cleanup = {
        firstShow: true,
        TweetCount: 0,
        tIds: [],
        tId: '',
        action: '',
        skip: 0,
        total: 0,
        dCount: 0,
        startCount: 0,
        startTime: 0,
        ratelimitreset: 0,
        pauseEvery: 190,
        pauseMinutes: 15,
        spareThreshold: 0,
        liveLikes: false,
        sparedCount: 0,
        deleteDMsOneByOne: false,
        bookmarks: [],
        bookmarksNext: '',
        _fails: 0,
        // Slow-delete session persistence: long runs leak memory inside X's own
        // page code until the tab crashes ("out of memory"). The session is
        // stored here so a wedged page can reload and resume where it left off.
        slowSessionKey: 'cleanup.slowSession',
        tweetResultQueryId: '7xflPyRiUxGVbJd4uWmbKg',
        deleteConvoURL: '/i/api/1.1/dm/conversation/USER_ID-CONVERSATION_ID/delete.json',
        bookmarksURL: '/i/api/graphql/L7vvM2UluPgWOW4GDvWyvw/Bookmarks?',

        onShow() { if (this.firstShow) { this.render(); this.firstShow = false; } },

        render() {
            UI.el('tpm-pane-cleanup').innerHTML = `
              <div class="tpm-section" id="tpm-slow-resume" style="display:none">
                <h4>Slow delete session in progress</h4>
                <p class="tpm-warn-box" style="margin:0 0 10px"><strong id="tpm-slow-resume-n">0</strong> deleted so far. If the timeline stays crashed for 60 minutes the page reloads itself to clear X's memory — resume the session here. <strong id="tpm-slow-resume-crash"></strong></p>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-primary" id="tpm-slow-resume-go" type="button">Resume deleting</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-slow-resume-stop" type="button">Stop session</button>
                </div>
              </div>
              <div class="tpm-section">
                <h4>Delete from your data export</h4>
                <p>Request your data at <a href="https://x.com/settings/your_twitter_data/data" target="_blank">Settings → Your data</a>, unzip it, then drop a file here.</p>
                <label id="tpm-drop" for="tpm-file">
                  <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="var(--acc)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16V4m0 0l-4 4m4-4l4 4"/><path d="M4 16v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2"/></svg>
                  <strong>Choose your data file</strong>
                  <span>Drag &amp; drop or click<br>tweet-headers.js · tweets.js · like.js · direct-message-headers.js</span>
                </label>
                <input type="file" id="tpm-file">
                <p id="tpm-clean-info" style="margin-top:12px"></p>
                <div id="tpm-clean-preview" style="display:none">
                  <div class="tpm-warn-box" id="tpm-clean-summary"></div>
                  <label class="tpm-check"><input type="checkbox" id="tpm-clean-confirm"> I understand this permanently deletes the items above. This cannot be undone.</label>
                  <div class="tpm-btns">
                    <button class="tpm-btn tpm-btn-ghost" id="tpm-clean-cancel" type="button">Cancel</button>
                    <button class="tpm-btn tpm-btn-danger" id="tpm-clean-start" type="button" disabled>Start deleting</button>
                  </div>
                </div>
                <div id="tpm-clean-progress"></div>
              </div>

              <div class="tpm-section">
                <h4>Filters</h4>
                <label class="tpm-label" for="tpm-skipCount">Skip the oldest N items (empty = auto-detect)</label>
                <input id="tpm-skipCount" type="number" class="tpm-input" placeholder="0">
                <label class="tpm-label" for="tpm-spareLikes">Spare tweets with more than N likes (needs tweets.js)</label>
                <input id="tpm-spareLikes" type="number" class="tpm-input" placeholder="e.g. 100">
                <label class="tpm-label" for="tpm-skipDays">Spare tweets from the last N days</label>
                <input id="tpm-skipDays" type="number" class="tpm-input" placeholder="e.g. 30">
                <label class="tpm-check"><input type="checkbox" id="tpm-liveLikes"> Fetch live like counts from X (works with tweet-headers.js; one extra request per tweet)</label>
              </div>

              <div class="tpm-section">
                <h4>Auto-pause</h4>
                <p>Pause periodically to dodge rate limits and account locks.</p>
                <div class="tpm-row">
                  <div><label class="tpm-label">Pause after every N</label><input id="tpm-pauseEvery" type="number" class="tpm-input" value="190"></div>
                  <div><label class="tpm-label">Pause (minutes)</label><input id="tpm-pauseMinutes" type="number" class="tpm-input" value="15"></div>
                </div>
              </div>

              <div class="tpm-section">
                <h4>Other tools</h4>
                <div class="tpm-btns"><button id="tpm-exportBookmarks" class="tpm-btn tpm-btn-ghost" type="button">Export bookmarks</button></div>
                <div class="tpm-btns"><button id="tpm-slowDelete" class="tpm-btn tpm-btn-ghost" type="button">Slow delete without a file</button></div>
                <p style="margin-top:10px">Slow delete works straight from your profile (no export), ~4000/hour. Only deletes tweets authored by you.</p>
              </div>
              <div class="tpm-foot">Cleanup engine: TweetXer v0.9.4 (adapted)</div>`;

            UI.el('tpm-file').addEventListener('change', () => this.processFile(), false);
            UI.el('tpm-exportBookmarks').onclick = () => this.exportBookmarks();
            UI.el('tpm-slowDelete').onclick = () => this.slowDelete();

            // Offer a one-click resume when a slow-delete session survived a reload.
            const session = Core.store.get(this.slowSessionKey, null);
            if (session && session.active) {
                UI.el('tpm-slow-resume').style.display = '';
                UI.el('tpm-slow-resume-n').textContent = (session.deleted || 0).toLocaleString();
                // No heartbeat for 5+ minutes means the previous page died (OOM,
                // tab closed, browser restart) — tell the user instead of implying
                // the run is still going.
                if (session.beat && Date.now() - session.beat > 300000) {
                    UI.el('tpm-slow-resume-crash').textContent = 'The page appears to have crashed — resume to continue.';
                }
                // Crash recoveries reload with autoResume set: continue hands-free.
                if (session.autoResume) {
                    const onProfile = Core.username && location.pathname.toLowerCase().includes(`/${Core.username.toLowerCase()}`);
                    if (onProfile) {
                        this.info('Resuming slow delete session…');
                        this.slowDelete(true);
                    } else if (Core.username && !Core.isReservedName(Core.username)) {
                        location.replace(`${Core.baseUrl}/${Core.username}`);
                    }
                }
            }
            UI.el('tpm-slow-resume-go').onclick = () => { this.info('Resuming…'); this.slowDelete(true); };
            UI.el('tpm-slow-resume-stop').onclick = () => {
                Core.store.set(this.slowSessionKey, null);
                UI.el('tpm-slow-resume').style.display = 'none';
                this.info('Slow delete session stopped.');
            };

            // Start/cancel for the previewed deletion run. The Start button stays
            // disabled until the user ticks the irreversible-action confirmation.
            UI.el('tpm-clean-confirm').addEventListener('change', (e) => {
                UI.el('tpm-clean-start').disabled = !e.target.checked;
            });
            UI.el('tpm-clean-start').onclick = () => this.startRun();
            UI.el('tpm-clean-cancel').onclick = () => this.cancelRun();

            // drag & drop
            const drop = UI.el('tpm-drop'), fileInput = UI.el('tpm-file');
            ['dragenter', 'dragover'].forEach(ev => drop.addEventListener(ev, (e) => { e.preventDefault(); e.stopPropagation(); drop.classList.add('tpm-dragover'); }));
            ['dragleave', 'drop'].forEach(ev => drop.addEventListener(ev, (e) => { e.preventDefault(); e.stopPropagation(); drop.classList.remove('tpm-dragover'); }));
            drop.addEventListener('drop', (e) => {
                if (e.dataTransfer.files?.length) { fileInput.files = e.dataTransfer.files; fileInput.dispatchEvent(new Event('change')); }
            });
        },

        info(text) { const el = UI.el('tpm-clean-info'); if (el) el.textContent = text; },

        readSettings() {
            const every = parseInt(UI.el('tpm-pauseEvery')?.value, 10);
            this.pauseEvery = isNaN(every) ? 190 : every;
            const mins = parseFloat(UI.el('tpm-pauseMinutes')?.value);
            this.pauseMinutes = isNaN(mins) ? 15 : mins;
            const likes = parseInt(UI.el('tpm-spareLikes')?.value, 10);
            this.spareThreshold = isNaN(likes) ? 0 : likes;
            this.liveLikes = !!UI.el('tpm-liveLikes')?.checked;
        },

        createProgressBar() {
            const drop = UI.el('tpm-drop'); if (drop) drop.style.display = 'none';
            this.startTime = Date.now();
            this.startCount = this.dCount;
            this._fails = 0;
            this._netRetries = {};
            const area = UI.el('tpm-clean-progress');
            area.innerHTML = `
              <div style="display:flex;justify-content:space-between;align-items:baseline;margin:6px 0">
                <span style="font-size:13px;color:var(--muted);font-weight:600">Progress</span>
                <span class="tpm-pct" id="tpm-pct">0%</span>
              </div>
              <div class="tpm-track"><div class="tpm-fill" id="tpm-fill" style="background:linear-gradient(90deg,var(--acc),#5cc0ff)"></div></div>
              <div style="display:flex;justify-content:space-between;gap:8px;margin-top:8px;font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums">
                <span id="tpm-cnt">0 / 0</span><span id="tpm-rate">—</span><span id="tpm-eta">ETA —</span>
              </div>`;
            this.updateProgressBar();
        },

        updateProgressBar() {
            if (!UI.el('tpm-fill')) return;
            const total = this.total || 0;
            const pct = total > 0 ? Math.min(100, (this.dCount / total) * 100) : 0;
            UI.el('tpm-fill').style.width = `${pct}%`;
            UI.el('tpm-pct').textContent = `${pct >= 100 ? '100' : pct.toFixed(1)}%`;
            UI.el('tpm-cnt').textContent = `${this.dCount.toLocaleString()} / ${total.toLocaleString()}`;
            const elapsed = (Date.now() - this.startTime) / 1000;
            const done = this.dCount - this.startCount;
            const rate = (done > 0 && elapsed > 0) ? done / elapsed : 0;
            UI.el('tpm-rate').textContent = rate <= 0 ? '—' : (rate >= 1 ? `${rate.toFixed(1)}/s` : `${(rate * 60).toFixed(0)}/min`);
            const remaining = Math.max(0, total - this.dCount);
            UI.el('tpm-eta').textContent = `ETA ${rate > 0 ? Core.fmtDuration(remaining / rate) : '—'}`;
            this.info(`Working… most recent ID: ${this.tId || '—'}`);
        },

        filterByLikes(entries) {
            if (UI.el('tpm-liveLikes')?.checked) return entries;
            const spareLikes = parseInt(UI.el('tpm-spareLikes')?.value, 10) || 0;
            if (spareLikes <= 0) return entries;
            if (!entries.length || entries[0].tweet.favorite_count === undefined) {
                this.info('This file has no like counts. Use tweets.js to spare tweets by likes.');
                return entries;
            }
            const before = entries.length;
            const kept = entries.filter(x => !(parseInt(x.tweet.favorite_count, 10) > spareLikes));
            console.log(`Sparing ${before - kept.length} tweet(s) with more than ${spareLikes} likes.`);
            return kept;
        },

        needsTweetsFileForLikes(json) {
            if (UI.el('tpm-liveLikes')?.checked) return false;
            const likes = parseInt(UI.el('tpm-spareLikes')?.value, 10);
            if (isNaN(likes) || likes <= 0) return false;
            return !json.length || json[0].tweet.favorite_count === undefined;
        },

        promptForTweetsFile() {
            this.info('Like-based sparing needs like counts, which tweet-headers.js lacks. Select tweets.js instead, or enable "Fetch live like counts".');
            const strong = document.querySelector('#tpm-drop strong'); if (strong) strong.textContent = 'Now choose tweets.js';
            const span = document.querySelector('#tpm-drop span'); if (span) span.innerHTML = 'tweets.js holds the like counts needed to spare popular tweets';
            const drop = UI.el('tpm-drop'); if (drop) drop.style.display = '';
        },

        filterByDays(ids) {
            const days = parseInt(UI.el('tpm-skipDays')?.value, 10) || 0;
            if (days <= 0) return ids;
            const cutoff = Date.now() - days * 86400000;
            const epoch = Core.snowflakeEpoch;
            const before = ids.length;
            const kept = ids.filter(id => { try { return Number((BigInt(id) >> 22n) + epoch) < cutoff; } catch (_) { return true; } });
            console.log(`Sparing ${before - kept.length} tweet(s) from the last ${days} day(s).`);
            return kept;
        },

        async maybePause() {
            if (!this.pauseEvery || this.pauseEvery <= 0) return;
            const done = this.dCount - this.startCount;
            if (done <= 0 || done % this.pauseEvery !== 0) return;
            let remaining = Math.round(this.pauseMinutes * 60);
            while (remaining > 0) {
                this.info(`Pausing ${Core.fmtDuration(remaining)} after ${done.toLocaleString()} deletions to avoid rate limits…`);
                await Core.sleep(1000); remaining--;
            }
        },

        async getLikeCount(id) {
            const variables = JSON.stringify({ tweetId: id, withCommunity: false, includePromotedContent: false, withVoice: false });
            const features = JSON.stringify({
                creator_subscriptions_tweet_preview_api_enabled: true, communities_web_enable_tweet_community_results_fetch: true,
                c9s_tweet_anatomy_moderator_badge_enabled: true, articles_preview_enabled: true, responsive_web_edit_tweet_api_enabled: true,
                graphql_is_translatable_rweb_tweet_is_translatable_enabled: true, view_counts_everywhere_api_enabled: true,
                longform_notetweets_consumption_enabled: true, responsive_web_twitter_article_tweet_consumption_enabled: true,
                tweet_awards_web_tipping_enabled: false, creator_subscriptions_quote_tweet_preview_enabled: false,
                freedom_of_speech_not_reach_fetch_enabled: true, standardized_nudges_misinfo: true,
                tweet_with_visibility_results_prefer_gql_limited_actions_policy_enabled: true, rweb_video_timestamps_enabled: true,
                longform_notetweets_rich_text_read_enabled: true, longform_notetweets_inline_media_enabled: true,
                responsive_web_graphql_exclude_directive_enabled: true, verified_phone_label_enabled: false,
                responsive_web_graphql_skip_user_profile_image_extensions_enabled: false, responsive_web_graphql_timeline_navigation_enabled: true,
                responsive_web_enhance_cards_enabled: false, rweb_tipjar_consumption_enabled: true, premium_content_api_read_enabled: false,
                responsive_web_grok_analyze_button_fetch_trends_enabled: false, responsive_web_grok_analyze_post_followups_enabled: false,
                responsive_web_grok_share_attachment_enabled: false, profile_label_improvements_pcf_label_in_post_enabled: false,
                responsive_web_grok_image_annotation_enabled: false, tweetypie_unmention_optimization_enabled: true
            });
            const fieldToggles = JSON.stringify({ withArticleRichContentState: true, withArticlePlainText: false, withGrokAnalyze: false, withDisallowedReplyControls: false });
            const url = `${Core.baseUrl}/i/api/graphql/${this.tweetResultQueryId}/TweetResultByRestId?` + new URLSearchParams({ variables, features, fieldToggles });
            for (let attempt = 0; attempt < 2; attempt++) {
                try {
                    const response = await fetch(url, {
                        headers: Core.apiHeaders(), referrer: `${Core.baseUrl}/${Core.username}`,
                        referrerPolicy: 'strict-origin-when-cross-origin', method: 'GET', mode: 'cors',
                        credentials: 'include', signal: AbortSignal.timeout(5000)
                    });
                    if (response.status === 200) {
                        const data = await response.json();
                        let result = data?.data?.tweetResult?.result;
                        if (result && result.tweet) result = result.tweet;
                        const likes = result?.legacy?.favorite_count;
                        return likes == null ? null : parseInt(likes, 10);
                    }
                    if (response.status === 429) {
                        const reset = parseInt(response.headers.get('x-rate-limit-reset'), 10);
                        let s = reset ? reset - Math.floor(Date.now() / 1000) : 60;
                        while (s > 0) { this.info(`Ratelimited reading likes. Waiting ${s}s. ${this.dCount} deleted.`); await Core.sleep(1000); s = reset ? reset - Math.floor(Date.now() / 1000) : s - 1; }
                        continue;
                    }
                    console.log(`Like lookup failed (HTTP ${response.status}). Update tweetResultQueryId if this persists.`);
                    return null;
                } catch (error) { console.log('Like lookup error:', error); return null; }
            }
            return null;
        },

        processFile() {
            const tn = UI.el('tpm-file');
            if (!(tn.files && tn.files[0])) return;
            const self = this;
            const fr = new FileReader();
            fr.onloadend = function (evt) {
                self.action = '';
                let filestart, json;
                try {
                    const cutpoint = evt.target.result.indexOf('= ');
                    filestart = evt.target.result.slice(0, cutpoint);
                    json = JSON.parse(evt.target.result.slice(cutpoint + 1));
                } catch (_) {
                    self.info('Could not read that file. Use an unmodified file from the X data export.');
                    return;
                }

                if (filestart.includes('.tweet_headers.')) {
                    if (self.needsTweetsFileForLikes(json)) { self.promptForTweetsFile(); return; }
                    self.action = 'untweet';
                    self.tIds = self.filterByDays(self.filterByLikes(json).map(x => x.tweet.tweet_id));
                } else if (filestart.includes('.tweets.') || filestart.includes('.tweet.')) {
                    self.action = 'untweet';
                    self.tIds = self.filterByDays(self.filterByLikes(json).map(x => x.tweet.id_str));
                } else if (filestart.includes('.like.')) {
                    self.action = 'unfav';
                    self.tIds = json.map(x => x.like.tweetId);
                } else if (filestart.includes('.direct_message_headers.') || filestart.includes('.direct_message_group_headers.') ||
                    filestart.includes('.direct_messages.') || filestart.includes('.direct_message_groups.')) {
                    self.action = 'undm';
                    if (self.deleteDMsOneByOne) {
                        self.tIds = json.map(c => c.dmConversation.messages.map(m => m.messageCreate ? m.messageCreate.id : 0)).flat().filter(i => i != 0);
                    } else {
                        self.tIds = json.map(c => c.dmConversation.conversationId);
                    }
                } else {
                    self.info('File content not recognized. Use a file from the Twitter data export.');
                }

                if (!self.action) return;   // unrecognized file; nothing to preview

                // Parse only. Build a run closure but DON'T delete yet — wait for the
                // explicit Start button so an irreversible action is never automatic.
                self.readSettings();
                self.total = self.tIds.length;

                const labels = { untweet: 'tweets', unfav: 'likes', undm: 'DM conversations' };
                // A run must never die silently: any throw inside the async delete
                // engines surfaces in the info line instead of an unhandled rejection.
                const failGuard = (p) => p.catch(err => {
                    console.error('[TPM] Run failed:', err);
                    self.info(`Run failed: ${(err && err.message) || err}. Check the console for details.`);
                });
                self._pendingRun = () => {
                    self.createProgressBar();
                    if (self.action === 'untweet') {
                        failGuard(self.ensureTweetCount().then(() => {
                            const skipVal = UI.el('tpm-skipCount').value;
                            if (skipVal.length < 1) {
                                self.skip = Math.max(0, self.total - self.TweetCount - parseInt(self.total / 20));
                            } else self.skip = parseInt(skipVal, 10);
                            console.log(`Skipping oldest ${self.skip} Tweets.`);
                            self.tIds.reverse();
                            self.tIds = self.tIds.slice(self.skip);
                            self.dCount = self.skip;
                            self.startCount = self.skip;
                            self.tIds.reverse();
                            return self.deleteTweets();
                        }));
                    } else if (self.action === 'unfav') {
                        self.skip = UI.el('tpm-skipCount').value.length > 0 ? parseInt(UI.el('tpm-skipCount').value, 10) : 0;
                        self.tIds = self.tIds.slice(self.skip);
                        self.dCount = self.skip;
                        self.startCount = self.skip;
                        self.tIds.reverse();
                        failGuard(self.deleteFavs());
                    } else if (self.action === 'undm') {
                        self.skip = UI.el('tpm-skipCount').value.length > 0 ? parseInt(UI.el('tpm-skipCount').value, 10) : 0;
                        self.tIds = self.tIds.slice(self.skip);
                        self.dCount = self.skip;
                        self.startCount = self.skip;
                        self.tIds.reverse();
                        failGuard(self.deleteDMsOneByOne ? self.deleteDMs() : self.deleteConvos());
                    }
                };

                self.showPreview(`Loaded <strong>${self.total.toLocaleString()}</strong> ${labels[self.action] || 'items'} from this file. Review the filters below, then start.`);
            };
            fr.readAsText(tn.files[0]);
        },

        // Reveal the confirm + Start controls after a file is parsed.
        showPreview(summaryHtml) {
            const box = UI.el('tpm-clean-summary'); if (box) box.innerHTML = summaryHtml;
            const wrap = UI.el('tpm-clean-preview'); if (wrap) wrap.style.display = '';
            const cb = UI.el('tpm-clean-confirm'); if (cb) cb.checked = false;
            const start = UI.el('tpm-clean-start'); if (start) start.disabled = true;
        },

        hidePreview() {
            const wrap = UI.el('tpm-clean-preview'); if (wrap) wrap.style.display = 'none';
        },

        // Fired by the Start button: run the stashed deletion.
        startRun() {
            if (!this._pendingRun) return;
            const run = this._pendingRun;
            this._pendingRun = null;
            this.hidePreview();
            run();
        },

        // Discard a parsed-but-not-started run and reset the file picker.
        cancelRun() {
            this._pendingRun = null;
            this.action = '';
            this.tIds = [];
            this.hidePreview();
            const fi = UI.el('tpm-file'); if (fi) fi.value = '';
            this.info('Cancelled. Drop a file to start over.');
        },

        // Lazily detect the profile tweet count (used to auto-skip already-deleted
        // tweets). Navigates to the profile only when needed.
        async ensureTweetCount() {
            if (this.TweetCount) return;
            try {
                await Core.waitForElem('header', 4000);
                const extract = (selector) => {
                    const el = document.querySelector(selector);
                    if (!el) return null;
                    const m = el.textContent.match(/((\d|,|\.|K)+) (\w+)$/);
                    if (!m) return null;
                    return m[1].replace(/\.(\d+)K/, '$1'.padEnd(4, '0')).replace('K', '000').replace(',', '').replace('.', '');
                };
                this.TweetCount = extract('[data-testid="primaryColumn"]>div>div>div') ||
                    extract('[data-testid="TopNavBar"]>div>div') || 1000000;
                console.log(this.TweetCount + ' Tweets on profile.');
            } catch (_) {
                this.TweetCount = 1000000;
            }
        },

        // Resolve a GraphQL endpoint URL using the LIVE query id when we can find
        // it (X rotates these; a stale id makes the API return 200 with an error
        // body and silently delete nothing). Falls back to the known-good id.
        async graphqlUrl(opName, fallbackId) {
            const id = (await Core.resolveQueryId(opName)) || fallbackId;
            return `${Core.baseUrl}/i/api/graphql/${id}/${opName}`;
        },

        async sendRequest(url, body = `{"variables":{"tweet_id":"${this.tId}","dark_request":false},"queryId":"${url.split('/')[6]}"}`) {
            return new Promise(async (resolve) => {
                try {
                    const response = await fetch(url, {
                        headers: Core.apiHeaders(), referrer: `${Core.baseUrl}/${Core.username}/with_replies`,
                        referrerPolicy: 'strict-origin-when-cross-origin', body, method: 'POST', mode: 'cors',
                        credentials: 'include', signal: AbortSignal.timeout(8000)
                    });
                    if (response.status === 200) {
                        // GraphQL returns HTTP 200 even when the mutation FAILS. Inspect
                        // the body so a failed delete is never counted as a success — the
                        // exact bug where the bar advanced but nothing was deleted.
                        let payload = null;
                        try { payload = await response.clone().json(); } catch (_) { }
                        if (payload && Array.isArray(payload.errors) && payload.errors.length) {
                            const msg = payload.errors[0]?.message || 'unknown GraphQL error';
                            this._fails = (this._fails || 0) + 1;
                            console.warn(`[TPM] Delete FAILED for ${this.tId}: ${msg}`, payload.errors);
                            this.info(`Delete failed: ${msg} (${this.dCount} done).`);
                            // Sustained failures => stale query id, expired login or rotated
                            // CSRF. Stop instead of burning the rest of the list doing nothing.
                            if (this._fails >= 15) {
                                this.tIds = [];
                                this.info(`Stopped: ${this._fails} consecutive failures. "${msg}". The delete query id or your login/CSRF token is likely stale — reload X and rerun.`);
                                console.error('[TPM] Aborting: repeated GraphQL failures.');
                            }
                            resolve('error');
                            return;
                        }
                        this._fails = 0;
                        this.dCount++;
                        if (this.dCount <= 3 || this.dCount % 50 === 0) console.log(`[TPM] Deleted ${this.dCount} (last id ${this.tId}).`);
                        this.updateProgressBar(); await this.maybePause();
                        if (response.headers.get('x-rate-limit-remaining') != null && response.headers.get('x-rate-limit-remaining') < 1) {
                            this.ratelimitreset = response.headers.get('x-rate-limit-reset');
                            let s = this.ratelimitreset - Math.floor(Date.now() / 1000);
                            while (s > 0) { s = this.ratelimitreset - Math.floor(Date.now() / 1000); this.info(`Ratelimited. Waiting ${s}s. ${this.dCount} deleted.`); await Core.sleep(1000); }
                            resolve('deleted and waiting');
                        } else resolve('deleted');
                    } else if (response.status === 429) {
                        // Push the id back and wait out the reset instead of retrying hot.
                        this.tIds.push(this.tId);
                        const reset = parseInt(response.headers.get('x-rate-limit-reset'), 10);
                        let s = reset ? reset - Math.floor(Date.now() / 1000) : 60;
                        while (s > 0) { s = reset ? reset - Math.floor(Date.now() / 1000) : s - 1; this.info(`Ratelimited (429). Waiting ${Math.max(0, s)}s. ${this.dCount} deleted.`); await Core.sleep(1000); }
                        resolve('ratelimited');
                    } else {
                        let detail = '';
                        try { detail = (await response.clone().text()).slice(0, 200); } catch (_) { }
                        this._fails = (this._fails || 0) + 1;
                        console.warn(`[TPM] Delete HTTP ${response.status} for ${this.tId}. ${detail}`);
                        this.info(`Delete failed (HTTP ${response.status}). ${this.dCount} done.`);
                        if (this._fails >= 15) {
                            this.tIds = [];
                            this.info(`Stopped: 15 consecutive HTTP ${response.status} errors. Reload X / re-log in and retry.`);
                        }
                        resolve('error');
                    }
                } catch (error) {
                    // Timeout or network error: retry the id a few times (queued last),
                    // then drop it — a hard cap so one bad id can't hang the run.
                    const isTimeout = error.name === 'AbortError' || error.Name === 'AbortError';
                    console.warn('[TPM] Delete request failed:', error);
                    this._netRetries = this._netRetries || {};
                    const n = (this._netRetries[this.tId] || 0) + 1;
                    if (n < 3) {
                        this._netRetries[this.tId] = n;
                        this.tIds.unshift(this.tId);
                        let s = isTimeout ? 15 : 3;
                        while (s > 0) { s--; this.info(`${isTimeout ? 'Timeout' : 'Network error'}. Waiting ${s}s. ${this.dCount} deleted.`); await Core.sleep(1000); }
                    } else {
                        delete this._netRetries[this.tId];
                        console.warn(`[TPM] Giving up on ${this.tId} after ${n} network failures.`);
                    }
                    resolve('error');
                }
            });
        },

        async deleteTweets() {
            const url = await this.graphqlUrl('DeleteTweet', 'VaenaVgh5q5ih7kvyVjgtg');
            console.log(`[TPM] Deleting ${this.tIds.length} tweets via ${url.split('/').slice(5).join('/')}`);
            while (this.tIds.length > 0) {
                this.tId = this.tIds.pop();
                if (this.liveLikes && this.spareThreshold > 0) {
                    const likes = await this.getLikeCount(this.tId);
                    if (likes !== null && likes > this.spareThreshold) {
                        this.sparedCount++; if (this.total > 0) this.total--;
                        console.log(`Spared ${this.tId} (${likes} likes).`); this.updateProgressBar(); continue;
                    }
                }
                await this.sendRequest(url);
            }
            this.tId = ''; this.updateProgressBar();
            this.info(`Done. Deleted ${this.dCount.toLocaleString()} tweets.`);
        },

        async deleteFavs() {
            const url = await this.graphqlUrl('UnfavoriteTweet', 'ZYKSe-w7KEslx3JhSIk5LA');
            while (this.tIds.length > 0) { this.tId = this.tIds.pop(); await this.sendRequest(url); }
            this.tId = ''; this.updateProgressBar(); this.info(`Done. Removed ${this.dCount.toLocaleString()} likes.`);
        },

        async deleteDMs() {
            const url = await this.graphqlUrl('DMMessageDeleteMutation', 'BJ6DtxA2llfjnRoRjaiIiw');
            while (this.tIds.length > 0) {
                this.tId = this.tIds.pop();
                await this.sendRequest(url, `{"variables":{"messageId":"${this.tId}"},"requestId":""}`);
            }
            this.tId = ''; this.updateProgressBar();
        },

        async deleteConvos() {
            const retries = {};
            while (this.tIds.length > 0) {
                this.tId = this.tIds.pop();
                const url = Core.baseUrl + this.deleteConvoURL.replace('USER_ID-CONVERSATION_ID', this.tId);
                let response;
                try {
                    response = await fetch(url, {
                        headers: Core.apiHeaders('application/x-www-form-urlencoded'), referrer: `${Core.baseUrl}/messages`,
                        body: 'dm_secret_conversations_enabled=false&krs_registration_enabled=true&cards_platform=Web-12&include_cards=1&include_ext_alt_text=true&include_ext_limited_action_results=true&include_quote_count=true&include_reply_count=1&tweet_mode=extended&include_ext_views=true&dm_users=false&include_groups=true&include_inbox_timelines=true&include_ext_media_color=true&supports_reactions=true&supports_edit=true&include_conversation_info=true',
                        method: 'POST', mode: 'cors', credentials: 'include', signal: AbortSignal.timeout(5000)
                    });
                } catch (error) {
                    // Timeout/network error: retry a few times, then skip — one bad
                    // request must not kill the whole run.
                    console.warn('[TPM] Convo delete request failed:', error);
                    retries[this.tId] = (retries[this.tId] || 0) + 1;
                    if (retries[this.tId] < 3) { this.tIds.unshift(this.tId); await Core.sleep(5000); }
                    continue;
                }
                if (response.status === 204) {
                    this.dCount++; this.updateProgressBar(); await this.maybePause();
                    if (response.headers.get('x-rate-limit-remaining') != null && response.headers.get('x-rate-limit-remaining') < 1) {
                        this.ratelimitreset = response.headers.get('x-rate-limit-reset');
                        let s = this.ratelimitreset - Math.floor(Date.now() / 1000);
                        while (s > 0) { s = this.ratelimitreset - Math.floor(Date.now() / 1000); this.info(`Ratelimited. Waiting ${s}s. ${this.dCount} deleted.`); await Core.sleep(1000); }
                    }
                    await Core.sleep(Math.floor(Math.random() * 200));
                } else if (response.status === 429 || response.status === 420) {
                    this.tIds.push(this.tId);
                    let s = 300; while (s > 0) { s--; this.info(`Ratelimited. Waiting ${s}s. ${this.dCount} deleted.`); await Core.sleep(1000); }
                } else console.log(response);
            }
            this.tId = ''; this.updateProgressBar();
        },

        async exportBookmarks() {
            this.info('Exporting bookmarks…');
            let variables = '';
            this.bookmarks = []; this.bookmarksNext = ''; this.dCount = 0;
            let fails = 0;
            while (this.bookmarksNext.length > 0 || this.bookmarks.length === 0) {
                variables = this.bookmarksNext.length > 0
                    ? `{"count":20,"cursor":"${this.bookmarksNext}","includePromotedContent":false}`
                    : '{"count":20,"includePromotedContent":false}';
                try {
                    const response = await fetch(Core.baseUrl + this.bookmarksURL + new URLSearchParams({
                        variables,
                        features: '{"graphql_timeline_v2_bookmark_timeline":true,"rweb_tipjar_consumption_enabled":true,"responsive_web_graphql_exclude_directive_enabled":true,"verified_phone_label_enabled":false,"creator_subscriptions_tweet_preview_api_enabled":true,"responsive_web_graphql_timeline_navigation_enabled":true,"responsive_web_graphql_skip_user_profile_image_extensions_enabled":false,"communities_web_enable_tweet_community_results_fetch":true,"c9s_tweet_anatomy_moderator_badge_enabled":true,"articles_preview_enabled":true,"responsive_web_edit_tweet_api_enabled":true,"graphql_is_translatable_rweb_tweet_is_translatable_enabled":true,"view_counts_everywhere_api_enabled":true,"longform_notetweets_consumption_enabled":true,"responsive_web_twitter_article_tweet_consumption_enabled":true,"tweet_awards_web_tipping_enabled":false,"creator_subscriptions_quote_tweet_preview_enabled":false,"freedom_of_speech_not_reach_fetch_enabled":true,"standardized_nudges_misinfo":true,"tweet_with_visibility_results_prefer_gql_limited_actions_policy_enabled":true,"rweb_video_timestamps_enabled":true,"longform_notetweets_rich_text_read_enabled":true,"longform_notetweets_inline_media_enabled":true,"responsive_web_enhance_cards_enabled":false}'
                    }), { headers: Core.apiHeaders(), referrer: `${Core.baseUrl}/i/bookmarks`, referrerPolicy: 'strict-origin-when-cross-origin', method: 'GET', mode: 'cors', credentials: 'include' });

                    if (response.status === 200) {
                        const data = await response.json();
                        const entries = data?.data?.bookmark_timeline_v2?.timeline?.instructions?.[0]?.entries || [];
                        entries.forEach((item) => {
                            if (item.entryId?.includes('tweet')) { this.dCount++; this.bookmarks.push(item.content?.itemContent?.tweet_results?.result); }
                            else if (item.entryId?.includes('cursor-bottom')) { this.bookmarksNext = this.bookmarksNext !== item.content.value ? item.content.value : ''; }
                        });
                        this.info(`${this.dCount} bookmarks collected`);
                        fails = 0;
                        const remaining = response.headers.get('x-rate-limit-remaining');
                        if (remaining != null && remaining < 1) {
                            this.ratelimitreset = response.headers.get('x-rate-limit-reset');
                            let s = this.ratelimitreset - Math.floor(Date.now() / 1000);
                            while (s > 0) { s = this.ratelimitreset - Math.floor(Date.now() / 1000); this.info(`Ratelimited. Waiting ${s}s. ${this.dCount} collected.`); await Core.sleep(1000); }
                        }
                    } else {
                        console.log(response);
                        if (++fails >= 5) { this.info(`Bookmark export stopped after ${fails} failed requests (${this.bookmarks.length} collected).`); break; }
                        await Core.sleep(3000);
                    }
                } catch (error) {
                    console.warn('[TPM] Bookmark export error:', error);
                    if (++fails >= 5) { this.info(`Bookmark export stopped after repeated errors (${this.bookmarks.length} collected).`); break; }
                    await Core.sleep(3000);
                }
            }
            if (!this.bookmarks.length) { this.info('No bookmarks collected.'); return; }
            const blob = new Blob([JSON.stringify(this.bookmarks)], { type: 'text/plain' });
            const a = document.createElement('a');
            a.innerText = 'Download bookmarks';
            a.href = window.URL.createObjectURL(blob);
            a.download = 'twitter-bookmarks.json';
            a.style.display = 'block'; a.style.marginTop = '10px';
            UI.el('tpm-clean-info').after(a);
            this.info(`Done — ${this.bookmarks.length} bookmarks ready to download.`);
        },

        tweetAuthorHandle(tweetEl) {
            const nameEl = tweetEl.querySelector('[data-testid="User-Name"]');
            const m = nameEl && nameEl.textContent.match(/@(\w+)/);
            return m ? m[1].toLowerCase() : null;
        },

        likesFromTweetElement(tweetEl) {
            const group = tweetEl.querySelector('[role="group"][aria-label]');
            const label = group ? group.getAttribute('aria-label') : '';
            const m = label.match(/([\d.,]+)\s*(K|M)?\s+like/i);
            if (!m) return 0;
            let n = parseFloat(m[1].replace(/,/g, ''));
            if (m[2] === 'K') n *= 1000; else if (m[2] === 'M') n *= 1000000;
            return Math.round(n);
        },

        // Best-effort post date from a rendered tweet. Prefers the <time> tag,
        // falls back to the snowflake id in the permalink. Null = unknown.
        tweetDate(tweetEl) {
            const dt = tweetEl.querySelector('time[datetime]')?.getAttribute('datetime');
            const t = dt ? Date.parse(dt) : NaN;
            if (!isNaN(t)) return new Date(t);
            const id = this.tweetStatusId(tweetEl);
            return id ? Core.snowflakeToDate(id) : null;
        },

        tweetStatusId(tweetEl) {
            const m = (tweetEl?.querySelector('a[href*="/status/"]')?.getAttribute('href') || '').match(/status\/(\d+)/);
            return m ? m[1] : null;
        },

        async slowDelete(resume = false) {
            let session = Core.store.get(this.slowSessionKey, null);
            if (resume) {
                if (!session || !session.active) return;
            } else {
                // Irreversible: require an explicit confirm before touching the profile.
                if (!window.confirm('Slow delete will permanently delete tweets straight from your profile. This cannot be undone. Continue?')) return;
                session = {
                    active: true, deleted: 0,
                    skipDays: UI.el('tpm-skipDays').value, spareLikes: UI.el('tpm-spareLikes').value,
                    liveLikes: UI.el('tpm-liveLikes').checked, pauseEvery: UI.el('tpm-pauseEvery').value,
                    pauseMinutes: UI.el('tpm-pauseMinutes').value
                };
            }
            // Restore the session's settings so this page lifetime continues the same job.
            UI.el('tpm-skipDays').value = session.skipDays || '';
            UI.el('tpm-spareLikes').value = session.spareLikes || '';
            UI.el('tpm-liveLikes').checked = !!session.liveLikes;
            UI.el('tpm-pauseEvery').value = session.pauseEvery || 190;
            UI.el('tpm-pauseMinutes').value = session.pauseMinutes || 15;
            // autoResume is consumed here; only the crash-recovery reloads set it again.
            session.autoResume = 0;
            Core.store.set(this.slowSessionKey, session);
            const endSession = () => Core.store.set(this.slowSessionKey, null);
            const rb = UI.el('tpm-slow-resume'); if (rb) rb.style.display = 'none';

            // X's heap can blow up mid-run ("Uncaught out of memory"). Watch for
            // those errors so the crash clock starts at the real moment of death
            // — a crashed-but-alive page reloads itself after 60 minutes crashed.
            if (!this._oomWatch) {
                this._oomWatch = (e) => {
                    const text = String((e && (e.message || e.reason)) || '');
                    if (!/out of memory|oom/i.test(text)) return;
                    const cur = Core.store.get(this.slowSessionKey, null);
                    if (cur && cur.active && !cur.crashedAt) {
                        cur.crashedAt = Date.now();
                        Core.store.set(this.slowSessionKey, cur);
                    }
                };
                window.addEventListener('error', this._oomWatch);
                window.addEventListener('unhandledrejection', this._oomWatch);
            }

            this.readSettings();
            const skipDays = parseInt(UI.el('tpm-skipDays')?.value, 10) || 0;
            const cutoff = Date.now() - skipDays * 86400000;
            const drop = UI.el('tpm-drop'); if (drop) drop.style.display = 'none';
            this.dCount = session.deleted || 0;
            let pageDeletes = 0;
            await this.ensureTweetCount();
            this.total = this.TweetCount;
            this.createProgressBar();

            const list = document.querySelectorAll('[data-testid="ScrollSnap-List"] a');
            if (list[1]) list[1].click();
            await Core.sleep(2000);

            // Guard against running on the wrong timeline (e.g. the infinite home
            // feed): slow delete only makes sense on your own profile page. If
            // we're elsewhere, go there and auto-start instead of bailing.
            if (Core.username && !location.pathname.toLowerCase().includes(`/${Core.username.toLowerCase()}`)) {
                session.autoResume = 1;
                Core.store.set(this.slowSessionKey, session);
                this.info('Opening your profile page to start the delete…');
                await Core.sleep(1000);
                location.replace(`${Core.baseUrl}/${Core.username}`);
                return;
            }

            let consecutiveErrors = 0;
            const maxConsecutiveErrors = 8;
            const more = '[data-testid="tweet"] [data-testid="caret"]';
            let emptyScans = 0;
            const maxEmptyScans = 12;
            let stuckCount = 0, lastTopId = '';
            let exitReason = '';
            let waitRounds = 0;
            const waitSeconds = 300;
            const stallReloadAfter = 3600;   // 1h of dead timeline => reload the page

            try {
            while (true) {
                await Core.sleep(1200);
                // Crash clock: once X has been out of memory for a full hour the
                // page will never recover on its own — reload for a clean heap.
                const live = Core.store.get(this.slowSessionKey, null);
                if (live && live.crashedAt && Date.now() - live.crashedAt >= 3600000) {
                    live.crashedAt = 0;
                    live.autoResume = 1;
                    Core.store.set(this.slowSessionKey, live);
                    this.info('Crashed for 60 minutes — reloading the page to recover. It resumes automatically.');
                    await Core.sleep(2000);
                    location.reload();
                    return;
                }
                document.querySelectorAll('section [data-testid="cellInnerDiv"]>div>div>div').forEach(x => x.remove());
                document.querySelectorAll('section [data-testid="cellInnerDiv"]>div>div>[role="link"]').forEach(x => x.remove());

                if (document.querySelectorAll(more).length === 0) {
                    const retry = Array.from(document.querySelectorAll('[role="button"], button')).find(b => /retry|try again|reload/i.test(b.textContent));
                    if (retry) retry.click();
                    window.scrollTo(0, document.body.scrollHeight);
                    if (++emptyScans >= maxEmptyScans) {
                        if (waitRounds * waitSeconds >= stallReloadAfter) {
                            // An hour of dead timeline: either the list is exhausted or the
                            // page is wedged (X leaks memory until it crashes). If this page
                            // lifetime deleted nothing AND the reload before it also deleted
                            // nothing, call it end-of-list; otherwise reload for a clean heap.
                            if (pageDeletes === 0) {
                                session.staleReloads = (session.staleReloads || 0) + 1;
                                if (session.staleReloads >= 2) {
                                    exitReason = 'the timeline stayed dead for over 2 hours across a reload — the list looks fully deleted';
                                    break;
                                }
                            } else session.staleReloads = 0;
                            session.crashedAt = 0;
                            session.autoResume = 1;
                            session.beat = Date.now();
                            Core.store.set(this.slowSessionKey, session);
                            this.info('Timeline dead for 60 minutes — reloading the page to recover. It resumes automatically.');
                            await Core.sleep(2000);
                            location.reload();
                            return;
                        }
                        // X rate-limits the timeline itself during bulk deletes.
                        // Wait it out, then keep trying instead of quitting.
                        waitRounds++;
                        session.beat = Date.now();
                        Core.store.set(this.slowSessionKey, session);
                        let s = waitSeconds;
                        while (s > 0) { s--; this.info(`Timeline stopped loading. Retrying in ${Core.fmtDuration(s)} (stalled ${Math.round((waitRounds * waitSeconds) / 60)}m of 60m). ${this.dCount} deleted.`); await Core.sleep(1000); }
                        emptyScans = 0;
                    }
                    await Core.sleep(6000); continue;
                }
                emptyScans = 0; waitRounds = 0;

                const caretEl = document.querySelector(more);
                const tweetEl = caretEl ? caretEl.closest('[data-testid="tweet"]') : document.querySelector('[data-testid="tweet"]');

                // Hang watchdog: if the same post sits on top for too many passes,
                // nothing advances (X silently refusing deletes, or a re-rendered
                // row). Try one recovery, then stop cleanly instead of spinning.
                const topId = this.tweetStatusId(tweetEl) || '';
                if (topId && topId === lastTopId) stuckCount++;
                else { stuckCount = 0; lastTopId = topId; }
                if (stuckCount === 10) {
                    document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
                    window.scrollTo(0, document.body.scrollHeight);
                }
                if (stuckCount >= 20) {
                    this.info(`Stopped: the same post stayed on top for 20 passes (likely an X rate limit). Wait 10-15 minutes, then press Resume above. ${this.dCount} deleted.`);
                    return;
                }

                if (tweetEl && Core.username) {
                    const author = this.tweetAuthorHandle(tweetEl);
                    if (author && author !== Core.username.toLowerCase()) { tweetEl.remove(); continue; }
                }
                if (tweetEl && skipDays > 0) {
                    const date = this.tweetDate(tweetEl);
                    // Unknown date => spare it; deleting on a guess is irreversible.
                    if (!date || date.getTime() > cutoff) { this.sparedCount++; if (this.total > 0) this.total--; tweetEl.remove(); this.updateProgressBar(); continue; }
                }
                if (tweetEl && this.spareThreshold > 0) {
                    const likes = this.likesFromTweetElement(tweetEl);
                    if (likes > this.spareThreshold) { this.sparedCount++; if (this.total > 0) this.total--; tweetEl.remove(); this.updateProgressBar(); continue; }
                }

                try {
                    const moreElement = document.querySelector(more);
                    if (moreElement) moreElement.scrollIntoView({ behavior: 'smooth' });

                    const unretweet = document.querySelector('[data-testid="unretweet"]');
                    if (unretweet) {
                        unretweet.click();
                        const confirmURT = await Core.waitForElem('[data-testid="unretweetConfirm"]');
                        if (!confirmURT) throw new Error('unretweet confirmation did not appear');
                        confirmURT.click();
                    } else {
                        const caret = await Core.waitForElem(more);
                        if (!caret) throw new Error('tweet menu button did not appear');
                        caret.click();
                        const menu = await Core.waitForElem('[role="menuitem"]');
                        if (!menu) throw new Error('tweet menu did not open');
                        if (menu.textContent.includes('@')) {
                            caret.click();
                            const notMine = moreElement.closest('[data-testid="tweet"]') || document.querySelector('[data-testid="tweet"]');
                            if (notMine) notMine.remove();
                        } else {
                            menu.click();
                            const confirmation = await Core.waitForElem('[data-testid="confirmationSheetConfirm"]');
                            if (!confirmation) throw new Error('delete confirmation did not appear');
                            confirmation.click();
                        }
                    }
                    this.dCount++; pageDeletes++;
                    session.deleted = this.dCount;
                    session.staleReloads = 0;
                    session.beat = Date.now();
                    Core.store.set(this.slowSessionKey, session);
                    this.updateProgressBar(); await this.maybePause();
                    consecutiveErrors = 0;
                    if (this.dCount % 100 === 0) console.log(`${new Date().toUTCString()} Deleted ${this.dCount} Tweets`);
                } catch (error) {
                    consecutiveErrors++;
                    document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
                    const backoff = Math.min(60000, 4000 * consecutiveErrors);
                    this.info(`Hit a snag (likely a rate limit). Waiting ${Math.round(backoff / 1000)}s. ${this.dCount} deleted.`);
                    await Core.sleep(backoff);
                    if (consecutiveErrors >= maxConsecutiveErrors) {
                        exitReason = `${maxConsecutiveErrors} consecutive UI errors (usually an X rate limit on deletions)`;
                        break;
                    }
                }
            }
            if (!exitReason) {
                endSession();
                this.info(`Finished. Total deleted: ${this.dCount} Tweets. Reload to confirm.`);
            } else if (exitReason.includes('fully deleted')) {
                endSession();
                this.info(`Finished. Total deleted: ${this.dCount} Tweets. ${exitReason}. Reload to confirm.`);
            } else {
                this.info(`Stopped early: ${exitReason}. ${this.dCount} deleted so far. Wait 10-15 minutes, then press Resume above.`);
            }
            } catch (err) {
                // OOM or DOM failure mid-run: keep the session alive so the user
                // can resume instead of losing the place in the list.
                console.error('[TPM] Slow delete crashed:', err);
                this.info(`Slow delete crashed (${(err && err.message) || err}). The session is saved — press Resume above to continue.`);
            }
        }
    };

/* ---- src/modules/followers.js ---- */
/**
 * @module followers
 * @description Follower tracker + following list sorted by following-count.
 * @see docs/modules/followers.md
 */
    /* ===================================================================== *
     *  FOLLOWERS — snapshot tracker + sort following by following-count     *
     * ===================================================================== */
    const Followers = {
        firstShow: true,
        running: false,
        stopFlag: false,
        // In-memory working set for the current sorted following scan
        rows: [],
        // Sort: 'following_desc' | 'following_asc' | 'followers_desc' | 'name'
        sortMode: Core.store.get('followersSort', 'following_desc'),
        enrichDelayMs: 900,

        onShow() {
            if (this.firstShow) {
                this.render();
                this.firstShow = false;
            }
            this.refreshSnapshotSummary();
            this.checkLocation();
        },

        render() {
            const pane = UI.el('tpm-pane-followers');
            if (!pane) return;
            pane.innerHTML = `
              <div class="tpm-warn-box">Walks your Following / Followers pages and looks up public profile stats. Stay on the list page while scanning. Respect rate limits — enrichment uses UserByScreenName (~1 req/account).</div>

              <div class="tpm-section">
                <h4>Follower tracker (snapshots)</h4>
                <p>Save a snapshot of your <strong>Followers</strong> list, then compare later to see who followed or left. Data stays in this browser (<code>localStorage</code>).</p>
                <div class="tpm-stats" id="tpm-f-snap-stats">
                  <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-f-snap-count">–</div><div class="tpm-stat-l">Last snapshot</div></div>
                  <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-f-snap-when">–</div><div class="tpm-stat-l">Taken</div></div>
                  <div class="tpm-stat"><div class="tpm-stat-v" id="tpm-f-hist-n">0</div><div class="tpm-stat-l">History</div></div>
                </div>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-primary" id="tpm-f-snap" type="button">Snapshot followers</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-diff" type="button">Diff vs previous</button>
                </div>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-export-snap" type="button">Export CSV</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-import-snap" type="button">Import CSV</button>
                </div>
                <div id="tpm-f-diff-out" class="tpm-note" style="margin-top:10px"></div>
              </div>

              <div class="tpm-section">
                <h4>Following list — sort by following count</h4>
                <p>Scan accounts on your <strong>Following</strong> page, fetch each account's following count, and list them sorted. Does not unfollow anyone.</p>
                <label class="tpm-label" for="tpm-f-sort">Sort by</label>
                <select id="tpm-f-sort" class="tpm-input">
                  <option value="following_desc">Following count (high → low)</option>
                  <option value="following_asc">Following count (low → high)</option>
                  <option value="followers_desc">Followers count (high → low)</option>
                  <option value="name">Handle (A–Z)</option>
                </select>
                <label class="tpm-label" for="tpm-f-max">Max accounts to enrich (0 = all scanned)</label>
                <input id="tpm-f-max" type="number" class="tpm-input" min="0" value="${Core.store.get('followersMax', 200)}">
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-primary" id="tpm-f-scan" type="button">Scan &amp; sort following</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-stop" type="button" disabled>Stop</button>
                </div>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-export" type="button" disabled>Export CSV</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-f-export-json" type="button" disabled>Export JSON</button>
                </div>
                <div class="tpm-status idle" id="tpm-f-status">Idle</div>
                <div class="tpm-now" id="tpm-f-now" style="display:none"></div>
              </div>

              <div class="tpm-section">
                <h4>Anti-bot follower cleanup</h4>
                <div id="tpm-antibot-host"></div>
              </div>

              <div class="tpm-section">
                <h4>Sorted results</h4>
                <div id="tpm-f-list" class="tpm-f-list"><p class="tpm-note">Run a scan to populate this table.</p></div>
              </div>
              <div class="tpm-foot">Follower tracker · v${Core.version}</div>`;

            UI.el('tpm-f-sort').value = this.sortMode;
            UI.el('tpm-f-sort').onchange = () => {
                this.sortMode = UI.el('tpm-f-sort').value;
                Core.store.set('followersSort', this.sortMode);
                this.renderTable();
            };
            UI.el('tpm-f-max').onchange = () => {
                Core.store.set('followersMax', parseInt(UI.el('tpm-f-max').value, 10) || 0);
            };
            UI.el('tpm-f-snap').onclick = () => this.snapshotFollowers();
            UI.el('tpm-f-diff').onclick = () => this.diffSnapshots();
            UI.el('tpm-f-export-snap').onclick = () => this.exportSnapshotCsv();
            UI.el('tpm-f-import-snap').onclick = () => this.importSnapshotCsv();
            UI.el('tpm-f-scan').onclick = () => this.scanAndSortFollowing();
            UI.el('tpm-f-stop').onclick = () => { this.stopFlag = true; };
            UI.el('tpm-f-export').onclick = () => this.exportCsv();
            UI.el('tpm-f-export-json').onclick = () => this.exportJson();
            this.refreshSnapshotSummary();
        },

        setStatus(kind, text) {
            const el = UI.el('tpm-f-status');
            if (!el) return;
            el.className = 'tpm-status ' + kind;
            el.textContent = text;
        },

        setNow(text) {
            const el = UI.el('tpm-f-now');
            if (!el) return;
            if (!text) { el.style.display = 'none'; return; }
            el.style.display = 'block';
            el.textContent = text;
        },

        checkLocation() {
            const path = location.pathname.toLowerCase();
            const onFollowers = /\/followers\/?$/.test(path) || /\/verified_followers\/?$/.test(path);
            const onFollowing = /\/following\/?$/.test(path);
            if (!onFollowers && !onFollowing) {
                this.setNow('Tip: open your profile → Followers (for snapshots) or Following (for sort scan).');
            }
        },

        // ---- Snapshot storage ------------------------------------------------

        _historyKey() { return 'followersHistory:' + (Core.username || 'me').toLowerCase(); },

        loadHistory() {
            return Core.store.get(this._historyKey(), []);
        },

        saveHistory(hist) {
            // Keep last 20 snapshots; on quota pressure drop oldest until it fits.
            let h = hist.slice(-20);
            while (h.length) {
                if (Core.store.set(this._historyKey(), h)) return true;
                h = h.slice(1);
            }
            return false;
        },

        // Shared snapshot writer: manual snapshots, anti-bot scans and CSV
        // imports all feed the same tracker history. Returns save success.
        saveSnapshot(accounts, source = 'manual') {
            const handles = accounts.map(a => (a.handle || '').toLowerCase()).sort();
            const snap = {
                at: new Date().toISOString(),
                username: Core.username || null,
                handles,
                meta: accounts,
                source
            };
            const hist = this.loadHistory();
            hist.push(snap);
            if (this.saveHistory(hist)) {
                console.log(`[TPM Followers] Snapshot (${source})`, snap);
                return true;
            }
            // Huge list: full details won't fit in browser storage. Keep the
            // handles only — still diffable — and retry.
            snap.meta = null;
            if (this.saveHistory(hist)) {
                console.warn('[TPM] Snapshot saved handles-only (list too large for full details).');
                return true;
            }
            console.warn('[TPM] Snapshot too large to save to browser storage.');
            return false;
        },

        // Latest snapshot -> CSV (handle,name,mutual,private).
        exportSnapshotCsv() {
            const hist = this.loadHistory();
            const snap = hist[hist.length - 1];
            if (!snap) { this.setNow('No snapshot to export yet.'); return; }
            const byHandle = {};
            (snap.meta || []).forEach(m => { if (m && m.handle) byHandle[m.handle.toLowerCase()] = m; });
            const header = 'handle,name,mutual,private';
            const lines = (snap.handles || []).map(h => {
                const m = byHandle[h] || {};
                return [h, JSON.stringify(m.name || ''), m.mutual ? 1 : 0, m.private ? 1 : 0].join(',');
            });
            this._download(`tpm-followers-snapshot-${(snap.at || '').slice(0, 10)}.csv`, [header, ...lines].join('\n'), 'text/csv');
        },

        // CSV (first column = handle) -> new snapshot, so imported lists can
        // be diffed against later scans.
        importSnapshotCsv() {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.csv,text/csv';
            input.onchange = () => {
                const file = input.files && input.files[0];
                if (!file) return;
                const fr = new FileReader();
                fr.onloadend = () => {
                    try {
                        const seen = new Set();
                        const accounts = [];
                        for (const line of String(fr.result).split(/\r?\n/)) {
                            const handle = line.split(',')[0].replace(/^"|"$/g, '').replace(/^@/, '').trim().toLowerCase();
                            if (!/^[a-z0-9_]{1,15}$/.test(handle) || seen.has(handle)) continue;
                            seen.add(handle);
                            accounts.push({ handle });
                        }
                        if (!accounts.length) { this.setNow('No valid handles found in that CSV.'); return; }
                        const saved = this.saveSnapshot(accounts, 'import');
                        this.refreshSnapshotSummary();
                        this.setNow(saved
                            ? `Imported ${accounts.length} handles as a snapshot. Use Diff vs previous to compare.`
                            : `Imported ${accounts.length} handles, but SAVE FAILED (browser storage full).`);
                    } catch (e) {
                        console.error('[TPM] Snapshot import failed:', e);
                        this.setNow('Import failed — is that a valid CSV?');
                    }
                };
                fr.readAsText(file);
            };
            input.click();
        },

        refreshSnapshotSummary() {
            const hist = this.loadHistory();
            const last = hist[hist.length - 1];
            const c = UI.el('tpm-f-snap-count');
            const w = UI.el('tpm-f-snap-when');
            const n = UI.el('tpm-f-hist-n');
            if (n) n.textContent = String(hist.length);
            if (!last) {
                if (c) c.textContent = '–';
                if (w) w.textContent = '–';
                return;
            }
            if (c) c.textContent = String(last.handles?.length || 0);
            if (w) {
                try {
                    const d = new Date(last.at);
                    const src = last.source && last.source !== 'manual' ? ` (${last.source})` : '';
                    w.textContent = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + src;
                } catch (_) { w.textContent = '–'; }
            }
        },

        /**
         * Collect the followers list via X's cursor-paginated Followers GraphQL
         * endpoint. Scales to 100k+ (no DOM scroll, no per-account lookups) and
         * returns locked status, follower count, default-avatar flag and id per
         * account. Returns null if the endpoint is unavailable (caller falls back
         * to the DOM walk), otherwise the collected array.
         */
        async collectFollowersApi(opts = {}) {
            const onProgress = opts.onProgress || (() => { });
            const userId = Core.userId;
            if (!userId) return null;
            const queryId = await Core.resolveQueryId('Followers');
            if (!queryId) return null;
            const features = Core.followersFeatures();
            const seen = new Map();
            let cursor = '';
            let pages = 0;
            let firstOk = false;
            const maxPages = opts.maxPages || 8000;
            while (pages < maxPages && !this.stopFlag) {
                const variables = { userId: String(userId), count: 20 };
                if (cursor) variables.cursor = cursor;
                const url = `${Core.baseUrl}/i/api/graphql/${queryId}/Followers?` + new URLSearchParams({
                    variables: JSON.stringify(variables), features
                });
                let res;
                try {
                    res = await fetch(url, {
                        headers: Core.apiHeaders(), referrer: `${Core.baseUrl}/${Core.username || ''}`,
                        referrerPolicy: 'strict-origin-when-cross-origin', method: 'GET', mode: 'cors',
                        credentials: 'include', signal: AbortSignal.timeout(10000)
                    });
                } catch (e) {
                    if (!firstOk) return null;
                    break;
                }
                if (res.status === 429) {
                    const reset = parseInt(res.headers.get('x-rate-limit-reset'), 10);
                    let s = reset ? reset - Math.floor(Date.now() / 1000) : 60;
                    while (s > 0 && !this.stopFlag) {
                        onProgress(seen.size, s);
                        await Core.sleep(1000);
                        s = reset ? reset - Math.floor(Date.now() / 1000) : s - 1;
                    }
                    continue;
                }
                if (res.status !== 200) { if (!firstOk) return null; break; }
                let data;
                try { data = await res.json(); } catch (e) { if (!firstOk) return null; break; }
                firstOk = true;
                const entries = data?.data?.user?.result?.timeline?.timeline?.entries || [];
                let added = 0;
                let nextCursor = '';
                for (const entry of entries) {
                    const eid = entry.entryId || '';
                    if (eid.includes('cursor-bottom')) { nextCursor = entry.content?.value || ''; continue; }
                    const user = entry.content?.itemContent?.user_results?.result;
                    const lg = user?.legacy;
                    if (!lg || !lg.screen_name) continue;
                    const key = lg.screen_name.toLowerCase();
                    if (seen.has(key)) continue;
                    seen.set(key, {
                        handle: lg.screen_name,
                        name: lg.name || lg.screen_name,
                        mutual: false,
                        private: !!lg.protected,
                        followers: lg.followers_count ?? null,
                        defaultImage: !!lg.default_profile_image,
                        bio: lg.description || '',
                        createdAt: lg.created_at || null,
                        id: user.rest_id || lg.id_str || null
                    });
                    added++;
                }
                pages++;
                onProgress(seen.size, 0);
                if (!nextCursor || added === 0) break;
                cursor = nextCursor;
                await Core.sleep(600 + Core.rand(0, 400));
            }
            return [...seen.values()];
        },

        // Best available collector: API pagination first (huge lists), DOM walk fallback.
        async collectFollowersBest(opts = {}) {
            const api = await this.collectFollowersApi(opts);
            if (Array.isArray(api) && api.length) return { accounts: api, viaApi: true };
            const accounts = await this.collectListHandles({ maxScrolls: 100000, stagnantLimit: 6 });
            return { accounts: accounts || [], viaApi: false };
        },

        /**
         * Walk the Followers list DOM (virtualized), collect unique handles.
         * Scrolls the page to load more rows until no growth or stop.
         */
        async collectListHandles(opts = {}) {
            const maxScrolls = opts.maxScrolls || 80;
            const settleMs = opts.settleMs || 700;
            const stagnantLimit = opts.stagnantLimit || 6;
            const seen = new Map(); // handle -> { handle, name, mutual, private }
            let stagnant = 0;

            for (let i = 0; i < maxScrolls && !this.stopFlag; i++) {
                const cells = document.querySelectorAll('[data-testid="UserCell"]');
                let added = 0;
                for (const cell of cells) {
                    // One malformed cell must not kill the whole walk.
                    try {
                        const handle = Follow.getUsername(cell);
                        if (!handle || handle === 'unknown') continue;
                        const key = handle.toLowerCase();
                        if (seen.has(key)) continue;
                        const nameEl = cell.querySelector('[dir="ltr"] span, a[role="link"] span');
                        seen.set(key, {
                            handle,
                            name: (nameEl && nameEl.textContent) || handle,
                            mutual: Follow.isMutual(cell),
                            private: Follow.isPrivate(cell)
                        });
                        added++;
                    } catch (_) { }
                }
                this.setNow(`Scanned ${seen.size} unique accounts… (scroll ${i + 1}/${maxScrolls})`);

                if (added === 0) {
                    // No new accounts: X is throttling the list (or it's the true
                    // end). Click Retry if offered, then give it REAL time to resume
                    // — a list rate limit lifts in tens of seconds, not two.
                    const retry = Array.from(document.querySelectorAll('[role="button"], button')).find(b => /retry|try again|reload/i.test(b.textContent));
                    if (retry) retry.click();
                    stagnant++;
                    if (stagnant >= stagnantLimit) break;
                    this.setNow(`List paused — waiting for X to load more (${stagnant}/${stagnantLimit})…`);
                    await Core.sleep(6000);
                    continue;
                }
                stagnant = 0;

                // Scroll the main timeline column to load the next batch.
                window.scrollBy(0, Math.min(window.innerHeight * 0.85, 900));
                await Core.sleep(settleMs);
            }
            return [...seen.values()];
        },

        async snapshotFollowers() {
            if (this.running) return;
            this.running = true;
            this.stopFlag = false;
            this._setBusy(true);
            this.setStatus('run', 'Snapshotting followers…');
            try {
                // API pagination first (works from any page, scales to 100k+);
                // DOM walk fallback needs the Followers page open.
                const { accounts, viaApi } = await this.collectFollowersBest({});
                if (this.stopFlag) { this.setStatus('stop', 'Stopped'); return; }
                if (!accounts.length) {
                    this.setStatus('pause', 'No followers collected — open your Followers page and retry.');
                    return;
                }
                const saved = this.saveSnapshot(accounts, 'manual');
                this.refreshSnapshotSummary();
                this.setStatus(saved ? 'idle' : 'stop',
                    saved ? `Saved ${accounts.length.toLocaleString()} followers${viaApi ? ' (API)' : ''}` : `Collected ${accounts.length.toLocaleString()}, but SAVE FAILED (browser storage full)`);
                this.setNow(`Snapshot saved (${accounts.length.toLocaleString()} handles). Use Diff vs previous to compare.`);
            } catch (e) {
                console.error(e);
                this.setStatus('stop', 'Snapshot failed');
            } finally {
                this.running = false;
                this._setBusy(false);
            }
        },

        diffSnapshots() {
            const hist = this.loadHistory();
            const out = UI.el('tpm-f-diff-out');
            if (!out) return;
            if (hist.length < 2) {
                out.innerHTML = 'Need at least <strong>two</strong> snapshots to diff. Take another later.';
                return;
            }
            const prev = hist[hist.length - 2];
            const curr = hist[hist.length - 1];
            const a = new Set(prev.handles || []);
            const b = new Set(curr.handles || []);
            const gained = [...b].filter(h => !a.has(h));
            const lost = [...a].filter(h => !b.has(h));
            out.innerHTML = `
              <strong>Diff</strong> ${Core.escapeHtml(prev.at?.slice(0, 10) || '?')} → ${Core.escapeHtml(curr.at?.slice(0, 10) || '?')}<br>
              <span style="color:var(--ok)">+${gained.length} new</span> ·
              <span style="color:var(--danger)">−${lost.length} lost</span>
              <div style="margin-top:8px;max-height:160px;overflow:auto;font-size:12px">
                ${gained.length ? '<div><strong>New:</strong> ' + gained.map(h => '@' + Core.escapeHtml(h)).join(', ') + '</div>' : ''}
                ${lost.length ? '<div style="margin-top:6px"><strong>Lost:</strong> ' + lost.map(h => '@' + Core.escapeHtml(h)).join(', ') + '</div>' : ''}
                ${!gained.length && !lost.length ? '<div>No changes between last two snapshots.</div>' : ''}
              </div>`;
            console.table({ gained: gained.length, lost: lost.length });
            if (gained.length) console.log('[TPM] New followers', gained);
            if (lost.length) console.log('[TPM] Lost followers', lost);
        },

        // ---- Sort following by following count -------------------------------

        async scanAndSortFollowing() {
            if (this.running) return;
            const path = location.pathname.toLowerCase();
            if (!/\/following\/?$/.test(path)) {
                this.setStatus('pause', 'Open your Following page first');
                alert('Go to your profile → Following, then run Scan & sort again.');
                return;
            }
            this.running = true;
            this.stopFlag = false;
            this.rows = [];
            this._setBusy(true);
            this.setStatus('run', 'Scanning Following list…');
            try {
                const accounts = await this.collectListHandles({ maxScrolls: 500, stagnantLimit: 6 });
                if (this.stopFlag) {
                    this.setStatus('stop', 'Stopped');
                    return;
                }
                const max = parseInt(UI.el('tpm-f-max')?.value, 10);
                const toEnrich = (!max || max <= 0) ? accounts : accounts.slice(0, max);
                this.setStatus('run', `Enriching ${toEnrich.length} profiles…`);

                for (let i = 0; i < toEnrich.length && !this.stopFlag; i++) {
                    const acc = toEnrich[i];
                    this.setNow(`Looking up @${acc.handle} (${i + 1}/${toEnrich.length})`);
                    const profile = await Core.fetchUserByScreenName(acc.handle, null, () => this.stopFlag);
                    this.rows.push({
                        handle: acc.handle,
                        name: profile?.name || acc.name,
                        following: profile?.following ?? null,
                        followers: profile?.followers ?? null,
                        location: profile?.location || '',
                        mutual: acc.mutual,
                        private: acc.private,
                        enriched: !!profile
                    });
                    // ponytail: render every 10th row, not every row — full-table innerHTML per row is O(n²)
                    if (i % 10 === 0 || i === toEnrich.length - 1) this.renderTable();
                    await Core.sleep(this.enrichDelayMs + Core.rand(0, 400));
                }

                // Include non-enriched remainder with null counts
                if (!max || max <= 0 || max >= accounts.length) {
                    /* all attempted */
                } else {
                    for (const acc of accounts.slice(max)) {
                        this.rows.push({
                            handle: acc.handle, name: acc.name,
                            following: null, followers: null, location: '',
                            mutual: acc.mutual, private: acc.private, enriched: false
                        });
                    }
                }

                this.renderTable();
                const ok = this.rows.filter(r => r.enriched).length;
                this.setStatus(this.stopFlag ? 'stop' : 'idle',
                    this.stopFlag ? `Stopped (${ok} enriched)` : `Done — ${ok} enriched, ${this.rows.length} total`);
                this.setNow(`Sorted by: ${this.sortMode}. Export if needed.`);
                UI.el('tpm-f-export').disabled = this.rows.length === 0;
                UI.el('tpm-f-export-json').disabled = this.rows.length === 0;
            } catch (e) {
                console.error(e);
                this.setStatus('stop', 'Scan failed');
            } finally {
                this.running = false;
                this._setBusy(false);
            }
        },

        sortRows() {
            const mode = this.sortMode || 'following_desc';
            const copy = this.rows.slice();
            if (mode === 'name') {
                copy.sort((a, b) => String(a.handle).localeCompare(String(b.handle)));
                return copy;
            }
            const key = mode.includes('followers') ? 'followers' : 'following';
            const asc = mode.endsWith('_asc');
            copy.sort((a, b) => {
                const av = a[key], bv = b[key];
                if (av == null && bv == null) return String(a.handle).localeCompare(String(b.handle));
                if (av == null) return 1; // nulls last
                if (bv == null) return -1;
                return asc ? av - bv : bv - av;
            });
            return copy;
        },

        renderTable() {
            const host = UI.el('tpm-f-list');
            if (!host) return;
            if (!this.rows.length) {
                host.innerHTML = '<p class="tpm-note">Run a scan to populate this table.</p>';
                return;
            }
            const sorted = this.sortRows();

            const rowsHtml = sorted.map((r, i) => `
              <tr>
                <td class="tpm-f-rank">${i + 1}</td>
                <td><a href="/${Core.escapeHtml(r.handle)}" target="_blank" rel="noopener">@${Core.escapeHtml(r.handle)}</a>
                  ${r.mutual ? '<span class="tpm-f-tag">mutual</span>' : ''}
                  ${r.private ? '<span class="tpm-f-tag">private</span>' : ''}
                </td>
                <td class="tpm-f-num">${r.following != null ? r.following.toLocaleString() : '—'}</td>
                <td class="tpm-f-num">${r.followers != null ? r.followers.toLocaleString() : '—'}</td>
                <td class="tpm-f-loc">${Core.escapeHtml(r.location || '—')}</td>
              </tr>`).join('');

            host.innerHTML = `
              <table class="tpm-f-table">
                <thead>
                  <tr>
                    <th>#</th><th>Handle</th>
                    <th title="How many accounts they follow">Following</th>
                    <th>Followers</th><th>Location</th>
                  </tr>
                </thead>
                <tbody>${rowsHtml}</tbody>
              </table>`;
        },

        exportCsv() {
            const sorted = this._exportRows();
            if (!sorted.length) return;
            const header = 'rank,handle,name,following,followers,location,mutual,private,enriched';
            const lines = sorted.map((r, i) => [
                i + 1,
                r.handle,
                JSON.stringify(r.name || ''),
                r.following ?? '',
                r.followers ?? '',
                JSON.stringify(r.location || ''),
                r.mutual ? 1 : 0,
                r.private ? 1 : 0,
                r.enriched ? 1 : 0
            ].join(','));
            this._download('tpm-following-sorted.csv', [header, ...lines].join('\n'), 'text/csv');
        },

        exportJson() {
            const sorted = this._exportRows();
            if (!sorted.length) return;
            this._download(
                'tpm-following-sorted.json',
                JSON.stringify({ at: new Date().toISOString(), sort: this.sortMode, rows: sorted }, null, 2),
                'application/json'
            );
        },

        _exportRows() {
            return this.sortRows();
        },

        _download(filename, text, mime) {
            const blob = new Blob([text], { type: mime });
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = filename;
            a.click();
            setTimeout(() => URL.revokeObjectURL(a.href), 2000);
        },

        _setBusy(busy) {
            const scan = UI.el('tpm-f-scan');
            const stop = UI.el('tpm-f-stop');
            const snap = UI.el('tpm-f-snap');
            if (scan) scan.disabled = busy;
            if (snap) snap.disabled = busy;
            if (stop) stop.disabled = !busy;
        }
    };

/* ---- src/modules/antibot.js ---- */
/**
 * @module antibot
 * @see docs/modules/antibot.md
 */
    /* ===================================================================== *
     *  ANTIBOT — flag and block bot-like followers. Scans the Followers      *
     *  page, enriches each account, classifies it against the filters,      *
     *  previews everything, and only blocks after explicit confirm.          *
     * ===================================================================== */
    const Antibot = {
        rows: [],
        running: false,
        stopFlag: false,

        render() {
            const host = UI.el('tpm-antibot-host');
            if (!host) return;
            const s = Core.store;
            host.innerHTML = `
              <p>Scans your <strong>Followers</strong> page and targets <strong>locked</strong> followers — the lock is read straight from the list (no API call). Only locked accounts get an API lookup. An account is shown only if it matches <strong>every</strong> selected filter. Nothing is blocked until you confirm.</p>
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-private" ${s.get('ab.private', true) ? 'checked' : ''}> Private / locked profile</label>
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-minon" ${s.get('ab.minon', true) ? 'checked' : ''}> Fewer followers than this minimum</label>
              <input id="tpm-ab-min" type="number" class="tpm-input" min="0" value="${s.get('ab.min', 10)}" style="max-width:120px">
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-avatar" ${s.get('ab.avatar', true) ? 'checked' : ''}> Default profile picture</label>
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-handle" ${s.get('ab.handle', true) ? 'checked' : ''}> Random / bot-like @handle</label>
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-bio" ${s.get('ab.bio', true) ? 'checked' : ''}> Empty bio</label>
              <label class="tpm-check"><input type="checkbox" id="tpm-ab-joinon" ${s.get('ab.joinon', true) ? 'checked' : ''}> Joined within the last N months</label>
              <input id="tpm-ab-joinmonths" type="number" class="tpm-input" min="1" value="${s.get('ab.joinmonths', 12)}" style="max-width:120px">
              <div class="tpm-btns">
                <button class="tpm-btn tpm-btn-primary" id="tpm-ab-scan" type="button">Scan followers</button>
                <button class="tpm-btn tpm-btn-ghost" id="tpm-ab-load" type="button">Load previous scan</button>
                <button class="tpm-btn tpm-btn-ghost" id="tpm-ab-stop" type="button" disabled>Stop</button>
              </div>
              <div class="tpm-status idle" id="tpm-ab-status">Idle — open your Followers page first.</div>
              <div id="tpm-ab-results"></div>`;
            UI.el('tpm-ab-scan').onclick = () => this.scan();
            UI.el('tpm-ab-load').onclick = () => this.loadPrevious();
            UI.el('tpm-ab-stop').onclick = () => { this.stopFlag = true; Followers.stopFlag = true; };
        },

        setStatus(kind, text) {
            const el = UI.el('tpm-ab-status');
            if (el) { el.className = 'tpm-status ' + kind; el.textContent = text; }
        },

        readFilters() {
            const s = Core.store;
            const f = {
                private: UI.el('tpm-ab-private').checked,
                minOn: UI.el('tpm-ab-minon').checked,
                min: parseInt(UI.el('tpm-ab-min').value, 10) || 0,
                avatar: UI.el('tpm-ab-avatar').checked,
                handle: UI.el('tpm-ab-handle').checked,
                emptyBio: UI.el('tpm-ab-bio').checked,
                joinOn: UI.el('tpm-ab-joinon').checked,
                joinMonths: parseInt(UI.el('tpm-ab-joinmonths').value, 10) || 12
            };
            s.set('ab.private', f.private); s.set('ab.minon', f.minOn); s.set('ab.min', f.min);
            s.set('ab.avatar', f.avatar); s.set('ab.handle', f.handle);
            s.set('ab.bio', f.emptyBio); s.set('ab.joinon', f.joinOn); s.set('ab.joinmonths', f.joinMonths);
            return f;
        },

        // Bot-like @handle signals: X's default "user<digits>" names, digit
        // runs, mostly-digit names, word+random-digits, vowel-less letter soup.
        handleSignals(handle) {
            const r = [];
            const s = String(handle || '').replace(/_/g, '');
            const digits = (s.match(/\d/g) || []).length;
            if (/^user\d{5,}$/i.test(s)) r.push('default "user…" name');
            if (/\d{4,}/.test(s)) r.push('long digit run');
            if (s.length >= 6 && digits / s.length >= 0.4) r.push('mostly digits');
            if (/^[a-z]+\d{2,}$/i.test(s)) r.push('word + random digits');
            const letters = s.replace(/\d/g, '');
            if (letters.length >= 6 && !/[aeiou]/i.test(letters)) r.push('no vowels');
            return r;
        },

        classify(row, f) {
            const checks = [];
            if (f.private) checks.push(row.private ? 'private' : null);
            if (f.minOn && f.min > 0) checks.push((row.followers != null && row.followers < f.min) ? `only ${row.followers} followers` : null);
            if (f.avatar) checks.push(row.defaultImage === true ? 'default avatar' : null);
            if (f.handle) {
                const hs = this.handleSignals(row.handle);
                checks.push(hs.length ? 'handle: ' + hs.join(', ') : null);
            }
            // Empty bio: only matches when we actually have bio data ('' = empty).
            if (f.emptyBio) checks.push((row.bio != null && String(row.bio).trim() === '') ? 'empty bio' : null);
            // Recent join: account created within the last N months.
            if (f.joinOn && f.joinMonths > 0) {
                const age = row.createdAt ? Date.now() - new Date(row.createdAt).getTime() : null;
                checks.push((age != null && !isNaN(age) && age < f.joinMonths * 30.44 * 86400000)
                    ? `joined ${Math.max(1, Math.round(age / 86400000))}d ago` : null);
            }
            // AND: a row only matches if EVERY selected filter matches it.
            // Nothing selected => nothing flagged.
            if (!checks.length) return [];
            return checks.every(c => c != null) ? checks : [];
        },

        // Rows decorated with match reasons under the CURRENT filters, so the
        // table always reflects whatever the user has ticked right now.
        matches() {
            const f = this.readFilters();
            return this.rows.map(row => Object.assign({}, row, { reasons: this.classify(row, f) }));
        },

        _dbKey() { return 'antibotScan:' + (Core.username || 'me').toLowerCase(); },

        // Re-show the last saved scan and re-apply the current filters — no API
        // calls, so the user can tune filters and instantly see different matches.
        loadPrevious() {
            if (this.running) return;
            const db = Core.store.get(this._dbKey(), null);
            if (!db || !db.rows || !db.rows.length) {
                this.setStatus('pause', 'No previous scan saved yet — run a scan first.');
                return;
            }
            this.rows = db.rows;
            this.renderResults();
            const flagged = this.matches().filter(x => x.reasons.length).length;
            const when = db.at ? new Date(db.at).toLocaleString() : 'unknown date';
            this.setStatus('idle', `Loaded previous scan (${when}): ${flagged} match all selected filters of ${this.rows.length} locked accounts.`);
        },

        async scan() {
            if (this.running) return;
            this.readFilters();
            this.running = true; this.stopFlag = false; Followers.stopFlag = false;
            UI.el('tpm-ab-scan').disabled = true; UI.el('tpm-ab-stop').disabled = false;
            this.setStatus('run', 'Collecting followers…');
            try {
                // API pagination first — scales to 100k+ followers and already
                // returns locked status, follower counts, avatar flag and ids
                // (works from any page). Falls back to the DOM walk, which reads
                // the lock icon from the list and looks up each locked account.
                let accounts = await Followers.collectFollowersApi({
                    onProgress: (n, waitS) => {
                        if (this.stopFlag) return;
                        if (waitS > 0) this.setStatus('pause', `Rate limited by X. Waiting ${Core.fmtDuration(waitS)} — ${n.toLocaleString()} followers collected. Press Stop to cancel.`);
                        else this.setStatus('run', `Collecting followers via API… ${n.toLocaleString()} so far.`);
                    }
                });
                let viaApi = Array.isArray(accounts) && accounts.length > 0;
                if (!viaApi) {
                    const path = location.pathname.toLowerCase();
                    if (!/\/(followers|verified_followers)\/?$/.test(path)) {
                        this.setStatus('pause', 'Open your Followers page first');
                        alert('The followers API is unavailable and the fallback needs your Followers page open. Go to your profile → Followers and scan again.');
                        return;
                    }
                    this.setStatus('run', 'API unavailable — collecting followers from the page…');
                    accounts = await Followers.collectListHandles({ maxScrolls: 100000, stagnantLimit: 6 });
                }
                if (this.stopFlag) { this.setStatus('stop', 'Stopped'); return; }
                if (!accounts || !accounts.length) { this.setStatus('stop', 'No followers collected.'); return; }

                // Feed the full follower list into the follower tracker so every
                // anti-bot scan doubles as a snapshot (diffable, exportable).
                const savedSnap = Followers.saveSnapshot(accounts, 'antibot');
                if (!savedSnap) console.warn('[TPM] Anti-bot snapshot save failed (browser storage full).');

                const locked = accounts.filter(a => a.private);
                this.rows = [];
                let failed = 0;
                if (viaApi) {
                    // Everything needed arrived with the list — no per-account lookups.
                    for (const a of locked) {
                        this.rows.push({
                            handle: a.handle, name: a.name, id: a.id || null,
                            private: true, followers: a.followers ?? null,
                            defaultImage: !!a.defaultImage,
                            bio: a.bio != null ? a.bio : '',
                            createdAt: a.createdAt || null,
                            enriched: true
                        });
                    }
                } else {
                    this.setStatus('run', `${locked.length} locked of ${accounts.length} followers — looking up the locked ones…`);
                    for (let i = 0; i < locked.length && !this.stopFlag; i++) {
                        const acc = locked[i];
                        Followers.setNow(`Anti-bot: looking up locked @${acc.handle} (${i + 1}/${locked.length})`);
                        // On a 429 the lookup waits out the reset, then resumes from
                        // this same index — the scan never loses its place. Stop is
                        // honored even in the middle of the wait.
                        const p = await Core.fetchUserByScreenName(acc.handle, (s) => {
                            this.setStatus('pause', `Rate limited by X. Waiting ${Core.fmtDuration(s)} — resumes at locked account ${i + 1}/${locked.length}. Press Stop to cancel.`);
                        }, () => this.stopFlag);
                        if (!p) failed++;
                        this.rows.push({
                            handle: acc.handle, name: p?.name || acc.name, id: p?.id || null,
                            private: true,
                            followers: p?.followers ?? null,
                            defaultImage: p ? !!p.defaultProfileImage : null,
                            bio: p ? (p.description || '') : null,
                            createdAt: p?.createdAt || null,
                            enriched: !!p
                        });
                        if (i % 10 === 0 || i === locked.length - 1) this.renderResults();
                        await Core.sleep(900 + Core.rand(0, 400));
                    }
                }
                // Persist the enriched scan so "Load previous scan" can re-apply
                // any filter combination later without new API calls.
                if (this.rows.length) {
                    const saved = Core.store.set(this._dbKey(), { at: new Date().toISOString(), rows: this.rows });
                    if (!saved) console.warn('[TPM] Anti-bot scan DB save failed (browser storage full).');
                }
                this.renderResults();
                const flagged = this.matches().filter(x => x.reasons.length).length;
                this.setStatus(this.stopFlag ? 'stop' : 'idle',
                    `${flagged} flagged of ${locked.length} locked (${accounts.length.toLocaleString()} followers collected${viaApi ? ' via API' : ''}${failed ? `, ${failed} lookups failed` : ''})`);
            } catch (e) {
                console.error('[TPM] Anti-bot scan failed:', e);
                this.setStatus('stop', 'Scan failed');
            } finally {
                this.running = false;
                UI.el('tpm-ab-scan').disabled = false; UI.el('tpm-ab-stop').disabled = true;
            }
        },

        renderResults() {
            const host = UI.el('tpm-ab-results');
            if (!host) return;
            if (!this.rows.length) { host.innerHTML = ''; return; }
            const all = this.matches();
            const flagged = all.filter(x => x.reasons.length);
            const blockable = flagged.filter(x => x.id);
            // Cap the rendered table — with huge follower lists a full table
            // would freeze the panel. Block/CSV still use every match.
            const shown = flagged.slice(0, 1000);
            const rowsHtml = shown.map(x => `
              <tr>
                <td><a href="/${Core.escapeHtml(x.handle)}" target="_blank" rel="noopener">@${Core.escapeHtml(x.handle)}</a></td>
                <td>${x.private ? 'yes' : 'no'}</td>
                <td class="tpm-f-num">${x.followers != null ? x.followers.toLocaleString() : '—'}</td>
                <td>${x.defaultImage == null ? '—' : x.defaultImage ? 'yes' : 'no'}</td>
                <td style="color:var(--muted)">${Core.escapeHtml(x.reasons.join('; '))}</td>
              </tr>`).join('');
            host.innerHTML = `
              <div style="margin-top:10px">
                <p><strong>${flagged.length}</strong> match all selected filters of ${this.rows.length} locked looked up${flagged.length > shown.length ? ` (showing first ${shown.length})` : ''}${flagged.length > blockable.length ? ` — ${blockable.length} blockable, the rest could not be looked up` : ''}.</p>
                <div class="tpm-f-list" style="max-height:220px;overflow:auto">
                  <table class="tpm-f-table">
                    <thead><tr><th>Handle</th><th>Private</th><th>Followers</th><th>Default pic</th><th>Matches</th></tr></thead>
                    <tbody>${rowsHtml || '<tr><td colspan="5">Nothing matches all selected filters.</td></tr>'}</tbody>
                  </table>
                </div>
                <div class="tpm-btns">
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-ab-csv" type="button">Export CSV</button>
                  <button class="tpm-btn tpm-btn-ghost" id="tpm-ab-json" type="button">Export JSON</button>
                </div>
                <label class="tpm-check"><input type="checkbox" id="tpm-ab-confirm"> I understand blocking removes these accounts from my followers.</label>
                <div class="tpm-btns"><button class="tpm-btn tpm-btn-danger" id="tpm-ab-block" type="button" disabled>Block ${blockable.length} matching followers</button></div>
              </div>`;
            UI.el('tpm-ab-confirm').addEventListener('change', (e) => { UI.el('tpm-ab-block').disabled = !e.target.checked || blockable.length === 0; });
            UI.el('tpm-ab-block').onclick = () => this.blockAll();
            UI.el('tpm-ab-csv').onclick = () => {
                const header = 'handle,name,private,followers,default_profile_image,empty_bio,created_at,matches_all_filters,reasons';
                const lines = all.map(x => [
                    x.handle, JSON.stringify(x.name || ''), x.private ? 1 : 0,
                    x.followers ?? '', x.defaultImage == null ? '' : (x.defaultImage ? 1 : 0),
                    x.bio != null && String(x.bio).trim() === '' ? 1 : 0,
                    x.createdAt ? new Date(x.createdAt).toISOString() : '',
                    x.reasons.length ? 1 : 0, JSON.stringify(x.reasons.join('; '))
                ].join(','));
                Followers._download('tpm-antibot-scan.csv', [header, ...lines].join('\n'), 'text/csv');
            };
            UI.el('tpm-ab-json').onclick = () => {
                Followers._download('tpm-antibot-scan.json', JSON.stringify({ at: new Date().toISOString(), rows: all }, null, 2), 'application/json');
            };
        },

        async blockAll() {
            const targets = this.matches().filter(x => x.reasons.length && x.id);
            if (!targets.length) return;
            if (!window.confirm(`Block ${targets.length} flagged followers? Blocking removes them as followers. You can only undo it by unblocking manually.`)) return;
            this.stopFlag = false;
            UI.el('tpm-ab-block').disabled = true; UI.el('tpm-ab-stop').disabled = false;
            let done = 0, failed = 0;
            for (let i = 0; i < targets.length && !this.stopFlag; i++) {
                const t = targets[i];
                this.setStatus('run', `Blocking @${t.handle} (${i + 1}/${targets.length})…`);
                try {
                    const res = await fetch(`${Core.baseUrl}/i/api/1.1/blocks/create.json`, {
                        headers: Core.apiHeaders('application/x-www-form-urlencoded'),
                        referrer: `${Core.baseUrl}/${Core.username}`,
                        body: `user_id=${t.id}`, method: 'POST', mode: 'cors', credentials: 'include',
                        signal: AbortSignal.timeout(8000)
                    });
                    if (res.ok) done++;
                    else if (res.status === 429) {
                        const reset = parseInt(res.headers.get('x-rate-limit-reset'), 10);
                        let s = reset ? reset - Math.floor(Date.now() / 1000) : 60;
                        while (s > 0 && !this.stopFlag) { s = reset ? reset - Math.floor(Date.now() / 1000) : s - 1; this.setStatus('pause', `Rate limited. Waiting ${Math.max(0, s)}s…`); await Core.sleep(1000); }
                        i--; continue;
                    } else {
                        failed++;
                        console.warn(`[TPM] Block HTTP ${res.status} for @${t.handle}`);
                    }
                } catch (e) {
                    failed++;
                    console.warn(`[TPM] Block failed for @${t.handle}:`, e);
                }
                await Core.sleep(1500 + Core.rand(0, 1500));
            }
            UI.el('tpm-ab-stop').disabled = true;
            this.setStatus(this.stopFlag ? 'stop' : 'idle', `Blocked ${done}, failed ${failed}. Reload your followers list to confirm.`);
        }
    };

/* ---- src/modules/about.js ---- */
